(function(){"use strict";var w=window.ScripturaJosephusWorks||(window.ScripturaJosephusWorks={});var a=w.apiao||(w.apiao={});a[1]={"work":"apiao","book":1,"title":"Φλαΐου Ἰωσήπου περὶ ἀρχαιότητος Ἰουδαίων λόγος α.","chapters":{"1":[{"number":1,"text":"Ἱκανῶς μὲν ὑπολαμβάνω καὶ διὰ τῆς περὶ τὴν ἀρχαιολογίαν συγγραφῆς, κράτιστε ἀνδρῶν Ἐπαφρόδιτε, τοῖς ἐντευξομένοις αὐτῇ πεποιηκέναι φανερὸν περὶ τοῦ γένους ἡμῶν τῶν Ἰουδαίων, ὅτι καὶ παλαιότατόν ἐστι καὶ τὴν πρώτην ὑπόστασιν ἔσχεν ἰδίαν, καὶ πῶς τὴν χώραν ἣν νῦν ἔχομεν κατῴκησε πεντακισχιλίων ἐτῶν ἀριθμὸν ἱστορίαν περιέχουσαν ἐκ τῶν παρʼ ἡμῖν ἱερῶν βίβλων διὰ τῆς Ἑλληνικῆς φωνῆς συνεγραψάμην."},{"number":2,"text":"ἐπεὶ δὲ συχνοὺς ὁρῶ ταῖς ὑπὸ δυσμενείας ὑπό τινων εἰρημέναις προσέχοντας βλασφημίαις καὶ τοῖς περὶ τὴν ἀρχαιολογίαν ὑπʼ ἐμοῦ γεγραμμένοις ἀπιστοῦντας τεκμήριόν τε ποιουμένους τοῦ νεώτερον εἶναι τὸ γένος ἡμῶν τὸ μηδεμιᾶς παρὰ τοῖς ἐπιφανέσι τῶν Ἑλληνικῶν ἱστοριογράφων μνήμης ἠξιῶσθαι,"},{"number":3,"text":"περὶ τούτων ἁπάντων ᾠήθην δεῖν γράψαι συντόμως τῶν μὲν λοιδορούντων τὴν δυσμένειαν καὶ τὴν ἑκούσιον ἐλέγξαι ψευδολογίαν, τῶν δὲ τὴν ἄγνοιαν ἐπανορθώσασθαι, διδάξαι δὲ πάντας, ὅσοι τἀληθὲς εἰδέναι βούλονται, περὶ τῆς ἡμετέρας ἀρχαιότητος."},{"number":4,"text":"χρήσομαι δὲ τῶν μὲν ὑπʼ ἐμοῦ λεγομένων μάρτυσι τοῖς ἀξιοπιστοτάτοις εἶναι περὶ πάσης ἀρχαιολογίας ὑπὸ τῶν Ἑλλήνων κεκριμένοις, τοὺς δὲ βλασφήμως περὶ ἡμῶν καὶ ψευδῶς γεγραφότας αὐτοὺς διʼ ἑαυτῶν ἐλεγχομένους παρέξω."},{"number":5,"text":"πειράσομαι δὲ καὶ τὰς αἰτίας ἀποδοῦναι, διʼ ἃς οὐ πολλοὶ τοῦ ἔθνους ἡμῶν ἐν ταῖς ἱστορίαις Ἕλληνες ἐμνημονεύκασιν, ἔτι μέντοι καὶ τοὺς οὐ παραλιπόντας τὴν περὶ ἡμῶν ἱστορίαν ποιήσω φανεροὺς τοῖς μὴ γιγνώσκουσιν ἢ προσποιουμένοις ἀγνοεῖν."},{"number":6,"text":"Πρῶτον οὖν ἐπέρχεταί μοι πάνυ θαυμάζειν τοὺς οἰομένους δεῖν περὶ τῶν παλαιοτάτων ἔργων μόνοις προσέχειν τοῖς Ἕλλησι καὶ παρὰ τούτων πυνθάνεσθαι τὴν ἀλήθειαν, ἡμῖν δὲ καὶ τοῖς ἄλλοις ἀνθρώποις ἀπιστεῖν· πᾶν γὰρ ἐγὼ τοὐναντίον ὁρῶ συμβεβηκός, εἴ γε δεῖ μὴ ταῖς ματαίαις δόξαις ἐπακολουθεῖν, ἀλλʼ ἐξ αὐτῶν τὸ δίκαιον τῶν πραγμάτων λαμβάνειν."},{"number":7,"text":"τὰ μὲν γὰρ παρὰ τοῖς Ἕλλησιν ἅπαντα νέα καὶ χθὲς καὶ πρῴην, ὡς ἂν εἴποι τις, εὕροι γεγονότα, λέγω δὲ τὰς κτίσεις τῶν πόλεων καὶ τὰ περὶ τὰς ἐπινοίας τῶν τεχνῶν καὶ τὰ περὶ τὰς τῶν νόμων ἀναγραφάς· πάντων δὲ νεωτάτη σχεδόν ἐστι παρʼ αὐτοῖς ἡ περὶ τὸ συγγράφειν τὰς ἱστορίας ἐπιμέλεια."},{"number":8,"text":"τὰ μέντοι παρʼ Αἰγυπτίοις τε καὶ Χαλδαίοις καὶ Φοίνιξιν, ἐῶ γὰρ νῦν ἡμᾶς ἐκείνοις συγκαταλέγειν, αὐτοὶ δήπουθεν ὁμολογοῦσιν ἀρχαιοτάτην τε καὶ μονιμωτάτην ἔχειν τῆς μνήμης τὴν παράδοσιν·"},{"number":9,"text":"καὶ γὰρ τόπους ἅπαντες οἰκοῦσιν ἥκιστα ταῖς ἐκ τοῦ περιέχοντος φθοραῖς ὑποκειμένους καὶ πολλὴν ἐποιήσαντο πρόνοιαν τοῦ μηδὲν ἄμνηστον τῶν παρʼ αὐτοῖς πραττομένων παραλιπεῖν, ἀλλʼ ἐν δημοσίαις ἀναγραφαῖς ὑπὸ τῶν σοφωτάτων ἀεὶ καθιεροῦσθαι."},{"number":10,"text":"τὸν δὲ περὶ τὴν Ἑλλάδα τόπον μυρίαι μὲν φθοραὶ κατέσχον ἐξαλείφουσαι τὴν μνήμην τῶν γεγονότων, ἀεὶ δὲ καινοὺς καθιστάμενοι βίους τοῦ παντὸς ἐνόμιζον ἄρχειν ἕκαστοι τῶν ἀφʼ ἑαυτῶν, ὀψὲ δὲ καὶ μόλις ἔγνωσαν φύσιν γραμμάτων· οἱ γοῦν ἀρχαιοτάτην αὐτῶν τὴν χρῆσιν εἶναι θέλοντες παρὰ Φοινίκων καὶ Κάδμου σεμνύνονται μαθεῖν."},{"number":11,"text":"οὐ μὴν οὐδὲ ἀπʼ ἐκείνου τοῦ χρόνου δύναιτό τις ἂν δεῖξαι σωζομένην ἀναγραφὴν οὔτʼ ἐν ἱεροῖς οὔτʼ ἐν δημοσίοις ἀναθήμασιν, ὅπου γε καὶ περὶ τῶν ἐπὶ Τροίαν τοσούτοις ἔτεσι στρατευσάντων ὕστερον πολλὴ γέγονεν ἀπορία τε καὶ ζήτησις, εἰ γράμμασιν ἐχρῶντο, καὶ τἀληθὲς ἐπικρατεῖ μᾶλλον περὶ τοῦ τὴν νῦν οὖσαν τῶν γραμμάτων χρῆσιν ἐκείνους ἀγνοεῖν."},{"number":12,"text":"ὅλως δὲ παρὰ τοῖς Ἕλλησιν οὐδὲν ὁμολογούμενον εὑρίσκεται γράμμα τῆς Ὁμήρου ποιήσεως πρεσβύτερον, οὗτος δὲ καὶ τῶν Τρωϊκῶν ὕστερος φαίνεται γενόμενος, καί φασιν οὐδὲ τοῦτον ἐν γράμμασι τὴν αὐτοῦ ποίησιν καταλιπεῖν, ἀλλὰ διαμνημονευομένην ἐκ τῶν ᾀσμάτων ὕστερον συντεθῆναι καὶ διὰ τοῦτο πολλὰς ἐν αὐτῇ σχεῖν τὰς διαφωνίας."},{"number":13,"text":"οἱ μέντοι τὰς ἱστορίας ἐπιχειρήσαντες συγγράφειν παρʼ αὐτοῖς, λέγω δὲ τοὺς περὶ Κάδμον τε τὸν Μιλήσιον καὶ τὸν Ἀργεῖον Ἀκουσίλαον καὶ μετὰ τοῦτον εἴ τινες ἄλλοι λέγονται γενέσθαι, βραχὺ τῆς Περσῶν ἐπὶ τὴν Ἑλλάδα στρατείας τῷ χρόνῳ προύλαβον."},{"number":14,"text":"ἀλλὰ μὴν καὶ τοὺς περὶ τῶν οὐρανίων τε καὶ θείων πρώτους παρʼ Ἕλλησι φιλοσοφήσαντας, οἷον Φερεκύδην τε τὸν Σύριον καὶ Πυθαγόραν καὶ Θάλητα, πάντες συμφώνως ὁμολογοῦσιν Αἰγυπτίων καὶ Χαλδαίων γενομένους μαθητὰς ὀλίγα συγγράψαι, καὶ ταῦτα τοῖς Ἕλλησιν εἶναι δοκεῖ πάντων ἀρχαιότατα καὶ μόλις αὐτὰ πιστεύουσιν ὑπʼ ἐκείνων γεγράφθαι."},{"number":15,"text":"Πῶς οὖν οὐκ ἔστιν ἄλογον τετυφῶσθαι τοὺς Ἕλληνας ὡς μόνους ἐπισταμένους τἀρχαῖα καὶ τὴν ἀλήθειαν περὶ αὐτῶν ἀκριβῶς παραδιδόντας; ἢ τίς οὐ παρʼ αὐτῶν ἂν τῶν συγγραφέων μάθοι ῥᾳδίως, ὅτι μηδὲν βεβαίως εἰδότες συνέγραφον, ἀλλʼ ὡς ἕκαστοι περὶ τῶν πραγμάτων εἴκαζον; τὸ πλεῖον γοῦν διὰ τῶν βιβλίων ἀλλήλους ἐλέγχουσι καὶ τἀναντιώτατα περὶ τῶν αὐτῶν λέγειν οὐκ ὀκνοῦσι."},{"number":16,"text":"περίεργος δʼ ἂν εἴην ἐγὼ τοὺς ἐμοῦ μᾶλλον ἐπισταμένους διδάσκων ὅσα μὲν Ἑλλάνικος Ἀκουσιλάῳ περὶ τῶν γενεαλογιῶν διαπεφώνηκεν, ὅσα δὲ διορθοῦται τὸν Ἡσίοδον Ἀκουσίλαος, ἢ τίνα τρόπον Ἔφορος μὲν Ἑλλάνικον ἐν τοῖς πλείστοις ψευδόμενον ἐπιδείκνυσιν, Ἔφορον δὲ Τίμαιος καὶ Τίμαιον οἱ μετʼ ἐκεῖνον γεγονότες, Ἡρόδοτον δὲ πάντες."},{"number":17,"text":"ἀλλʼ οὐδὲ περὶ τῶν Σικελικῶν τοῖς περὶ Ἀντίοχον καὶ Φίλιστον ἢ Καλλίαν Τίμαιος συμφωνεῖν ἠξίωσεν, οὐδʼ αὖ περὶ τῶν Ἀττικῶν οἱ τὰς Ἀτθίδας συγγεγραφότες ἢ περὶ τῶν Ἀργολικῶν οἱ τὰ περὶ Ἄργος ἱστοροῦντες ἀλλήλοις κατηκολουθήκασι."},{"number":18,"text":"καὶ τί δεῖ λέγειν περὶ τῶν κατὰ πόλεις καὶ βραχυτέρων; ὅπου γε περὶ τῆς Περσικῆς στρατείας καὶ τῶν ἐν αὐτῇ πραχθέντων οἱ δοκιμώτατοι διαπεφωνήκασι, πολλὰ δὲ καὶ Θουκυδίδης ὡς ψευδόμενος ὑπό τινων κατηγορεῖται καίτοι δοκῶν ἀκριβεστάτην τὴν καθʼ αὑτὸν ἱστορίαν συγγράφειν."},{"number":19,"text":"Αἰτίαι δὲ τῆς τοιαύτης διαφωνίας πολλαὶ μὲν ἴσως ἂν καὶ ἕτεραι τοῖς βουλομένοις ζητεῖν ἂν φανεῖεν, ἐγὼ δὲ δυσὶ ταῖς λεχθησομέναις τὴν μεγίστην ἰσχὺν ἀνατίθημι, καὶ προτέραν ἐρῶ τὴν κυριωτέραν εἶναί μοι δοκοῦσαν·"},{"number":20,"text":"τὸ γὰρ ἐξ ἀρχῆς μὴ σπουδασθῆναι παρὰ τοῖς Ἕλλησι δημοσίας γίνεσθαι περὶ τῶν ἑκάστοτε πραττομένων ἀναγραφὰς τοῦτο μάλιστα δὴ καὶ τὴν πλάνην καὶ τὴν ἐξουσίαν τοῦ ψεύδεσθαι τοῖς μετὰ ταῦτα βουληθεῖσι περὶ τῶν παλαιῶν τι γράφειν παρέσχεν."},{"number":21,"text":"οὐ γὰρ μόνον παρὰ τοῖς ἄλλοις Ἕλλησιν ἠμελήθη τὰ περὶ τὰς ἀναγραφάς, ἀλλʼ οὐδὲ παρὰ τοῖς Ἀθηναίοις, οὓς αὐτόχθονας εἶναι λέγουσιν καὶ παιδείας ἐπιμελεῖς, οὐδὲν τοιοῦτον εὑρίσκεται γενόμενον, ἀλλὰ τῶν δημοσίων γραμμάτων ἀρχαιοτάτους εἶναί φασι τοὺς ὑπὸ Δράκοντος αὐτοῖς περὶ τῶν φονικῶν γραφέντας νόμους ὀλίγῳ πρότερον τῆς Πεισιστράτου τυραννίδος ἀνθρώπου γεγονότος."},{"number":22,"text":"περὶ μὲν γὰρ Ἀρκάδων τί δεῖ λέγειν αὐχούντων ἀρχαιότητα; μόλις γὰρ οὗτοι καὶ μετὰ ταῦτα γράμμασιν ἐπαιδεύθησαν."},{"number":23,"text":"Ἅτε δὴ τοίνυν οὐδεμιᾶς προκαταβεβλημένης ἀναγραφῆς, ἣ καὶ τοὺς μαθεῖν βουλομένους διδάξειν ἔμελλεν καὶ τοὺς ψευδομένους ἐλέγξειν, ἡ πολλὴ πρὸς ἀλλήλους ἐγένετο διαφωνία τοῖς συγγραφεῦσι."},{"number":24,"text":"δευτέραν δὲ πρὸς ταύτῃ θετέον ἐκείνην αἰτίαν· οἱ γὰρ ἐπὶ τὸ γράφειν ὁρμήσαντες οὐ περὶ τὴν ἀλήθειαν ἐσπούδασαν, καίτοι τοῦτο πρόχειρόν ἐστιν ἀεὶ τὸ ἐπάγγελμα, λόγων δὲ δύναμιν ἐπεδείκνυντο,"},{"number":25,"text":"καὶ καθʼ ὅντινα τρόπον ἐν τούτῳ παρευδοκιμήσειν τοὺς ἄλλους ὑπελάμβανον, κατὰ τοῦτον ἡρμόζοντο τινὲς μὲν ἐπὶ τὸ μυθολογεῖν τραπόμενοι, τινὲς δὲ πρὸς χάριν ἢ τὰς πόλεις ἢ τοὺς βασιλέας ἐπαινοῦντες· ἄλλοι δὲ ἐπὶ τὸ κατηγορεῖν τῶν πράξεων ἢ τῶν γεγραφότων ἐχώρησαν ἐνευδοκιμήσειν τούτῳ νομίζοντες."},{"number":26,"text":"ὅλως δὲ τὸ πάντων ἐναντιώτατον ἱστορίᾳ πράττοντες διατελοῦσι· τῆς μὲν γὰρ ἀληθοῦς ἐστι τεκμήριον ἱστορίας, εἰ περὶ τῶν αὐτῶν ἅπαντες ταὐτὰ καὶ λέγοιεν καὶ γράφοιεν. οἱ δʼ εἰ ταῦτα γράψειαν ἑτέρως, οὕτως ἐνόμιζον αὐτοὶ φανεῖσθαι πάντων ἀληθέστατοι."},{"number":27,"text":"λόγων μὲν οὖν ἕνεκα καὶ τῆς ἐν τούτοις δεινότητος δεῖ παραχωρεῖν ἡμᾶς τοῖς συγγραφεῦσι τοῖς Ἑλληνικοῖς, οὐ μὴν καὶ τῆς περὶ τῶν ἀρχαίων ἀληθοῦς ἱστορίας καὶ μάλιστά γε τῆς περὶ τῶν ἑκάστοις ἐπιχωρίων."},{"number":28,"text":"Ὅτι μὲν οὖν παρʼ Αἰγυπτίοις τε καὶ Βαβυλωνίοις ἐκ μακροτάτων ἄνωθεν χρόνων τὴν περὶ τὰς ἀναγραφὰς ἐπιμέλειαν ὅπου μὲν οἱ ἱερεῖς ἦσαν ἐγκεχειρισμένοι καὶ περὶ ταύτας ἐφιλοσόφουν, Χαλδαῖοι δὲ παρὰ τοῖς Βαβυλωνίοις, καὶ ὅτι μάλιστα δὴ τῶν Ἕλλησιν ἐπιμιγνυμένων ἐχρήσαντο Φοίνικες γράμμασιν εἴς τε τὰς περὶ τὸν βίον οἰκονομίας καὶ πρὸς τὴν τῶν κοινῶν ἔργων παράδοσιν, ἐπειδὴ συγχωροῦσιν ἅπαντες, ἐάσειν μοι δοκῶ."},{"number":29,"text":"περὶ δὲ τῶν ἡμετέρων προγόνων ὅτι τὴν αὐτήν, ἐῶ γὰρ λέγειν εἰ καὶ πλείω τῶν εἰρημένων ἐποιήσαντο περὶ τὰς ἀναγραφὰς ἐπιμέλειαν τοῖς ἀρχιερεῦσι καὶ τοῖς προφήταις τοῦτο προστάξαντες, καὶ ὡς μέχρι τῶν καθʼ ἡμᾶς χρόνων πεφύλακται μετὰ πολλῆς ἀκριβείας, εἰ δὲ δεῖ θρασύτερον εἰπεῖν καὶ φυλαχθήσεται, πειράσομαι συντόμως διδάσκειν."},{"number":30,"text":"Οὐ γὰρ μόνον ἐξ ἀρχῆς ἐπὶ τούτων τοὺς ἀρίστους καὶ τῇ θεραπείᾳ τοῦ θεοῦ προσεδρεύοντας κατέστησαν, ἀλλʼ ὅπως τὸ γένος τῶν ἱερέων ἄμικτον καὶ καθαρὸν διαμενεῖ προυνόησαν."},{"number":31,"text":"δεῖ γὰρ τὸν μετέχοντα τῆς ἱερωσύνης ἐξ ὁμοεθνοῦς γυναικὸς παιδοποιεῖσθαι καὶ μὴ πρὸς χρήματα μηδὲ τὰς ἄλλας ἀποβλέπειν τιμὰς, ἀλλὰ τὸ γένος ἐξετάζειν ἐκ τῶν ἀρχαίων λαμβάνοντα τὴν διαδοχὴν καὶ πολλοὺς παρεχόμενον μάρτυρας."},{"number":32,"text":"καὶ ταῦτα πράττομεν οὐ μόνον ἐπʼ αὐτῆς Ἰουδαίας, ἀλλʼ ὅπου ποτὲ σύστημα τοῦ γένους ἐστὶν ἡμῶν κἀκεῖ τὸ ἀκριβὲς ἀποσώζεται τοῖς ἱερεῦσι περὶ τοὺς γάμους·"},{"number":33,"text":"λέγω δὲ τοὺς ἐν Αἰγύπτῳ καὶ Βαβυλῶνι καὶ εἴ που τῆς ἄλλης οἰκουμένης τοῦ γένους τῶν ἱερέων εἰσί τινες διεσπαρμένοι· πέμπουσι γὰρ εἰς Ἱεροσόλυμα συγγράψαντες πατρόθεν τοὔνομα τῆς τε γαμετῆς καὶ τῶν ἐπάνω προγόνων καὶ τίνες οἱ μαρτυροῦντες."},{"number":34,"text":"πόλεμος δʼ εἰ κατάσχοι, καθάπερ ἤδη γέγονεν πολλάκις Ἀντιόχου τε τοῦ Ἐπιφανοῦς εἰς τὴν χώραν ἐμβαλόντος καὶ Πομπηίου Μάγνου καὶ Κυντιλίου Οὐάρου μάλιστα δὲ καὶ ἐν τοῖς καθʼ ἡμᾶς χρόνοις,"},{"number":35,"text":"οἱ περιλειπόμενοι τῶν ἱερέων καινὰ πάλιν ἐκ τῶν ἀρχαίων γραμμάτων συνίστανται καὶ δοκιμάζουσι τὰς ὑπολειφθείσας γυναῖκας. οὐ γὰρ ἐπὶ τὰς αἰχμαλώτους γενομένας προσίενται πολλάκις γεγονυιῶν αὐταῖς τὴν πρὸς ἀλλόφυλον κοινωνίαν ὑφορώμενοι."},{"number":36,"text":"τεκμήριον δὲ μέγιστον τῆς ἀκριβείας· οἱ γὰρ ἀρχιερεῖς οἱ παρʼ ἡμῖν ἀπὸ δισχιλίων ἐτῶν ὀνομαστοὶ παῖδες ἐκ πατρὸς εἰσὶν ἐν ταῖς ἀναγραφαῖς. τοῖς δὲ τῶν εἰρημένων ὁτιοῦν γένοιτο εἰς παράβασιν ἀπηγόρευται μήτε τοῖς βωμοῖς παρίστασθαι μήτε μετέχειν τῆς ἄλλης ἁγιστείας."},{"number":37,"text":"εἰκότως οὖν, μᾶλλον δὲ ἀναγκαίως, ἅτε μήτε τὸ ὑπογράφειν αὐτεξουσίου πᾶσιν ὄντος μήτε τινὸς ἐν τοῖς γραφομένοις ἐνούσης διαφωνίας, ἀλλὰ μόνον τῶν προφητῶν τὰ μὲν ἀνωτάτω καὶ παλαιότατα κατὰ τὴν ἐπίπνοιαν τὴν ἀπὸ τοῦ θεοῦ μαθόντων, τὰ δὲ καθʼ αὑτοὺς ὡς ἐγένετο σαφῶς συγγραφόντων,"},{"number":38,"text":"οὐ μυριάδες βιβλίων εἰσὶ παρʼ ἡμῖν ἀσυμφώνων καὶ μαχομένων, δύο δὲ μόνα πρὸς τοῖς εἴκοσι βιβλία τοῦ παντὸς ἔχοντα χρόνου τὴν ἀναγραφήν, τὰ δικαίως πεπιστευμένα."},{"number":39,"text":"καὶ τούτων πέντε μέν ἐστι Μωυσέως, ἃ τούς τε νόμους περιέχει καὶ τὴν ἀπʼ ἀνθρωπογονίας παράδοσιν μέχρι τῆς αὐτοῦ τελευτῆς· οὗτος ὁ χρόνος ἀπολείπει τρισχιλίων ὀλίγῳ ἐτῶν."},{"number":40,"text":"ἀπὸ δὲ τῆς Μωυσέως τελευτῆς μέχρι τῆς Ἀρταξέρξου τοῦ μετὰ Ξέρξην Περσῶν βασιλέως οἱ μετὰ Μωυσῆν προφῆται τὰ κατʼ αὐτοὺς πραχθέντα συνέγραψαν ἐν τρισὶ καὶ δέκα βιβλίοις· αἱ δὲ λοιπαὶ τέσσαρες ὕμνους εἰς τὸν θεὸν καὶ τοῖς ἀνθρώποις ὑποθήκας τοῦ βίου περιέχουσιν."},{"number":41,"text":"ἀπὸ δὲ Ἀρταξέρξου μέχρι τοῦ καθʼ ἡμᾶς χρόνου γέγραπται μὲν ἕκαστα, πίστεως δʼ οὐχ ὁμοίας ἠξίωται τοῖς πρὸ αὐτῶν διὰ τὸ μὴ γενέσθαι τὴν τῶν προφητῶν ἀκριβῆ διαδοχήν."},{"number":42,"text":"δῆλον δʼ ἐστὶν ἔργῳ, πῶς ἡμεῖς πρόσιμεν τοῖς ἰδίοις γράμμασι· τοσούτου γὰρ αἰῶνος ἤδη παρῳχηκότος οὔτε προσθεῖναί τις οὐδὲν οὔτε ἀφελεῖν αὐτῶν οὔτε μεταθεῖναι τετόλμηκεν, πᾶσι δὲ σύμφυτόν ἐστιν εὐθὺς ἐκ πρώτης γενέσεως Ἰουδαίοις τὸ νομίζειν αὐτὰ θεοῦ δόγματα καὶ τούτοις ἐμμένειν καὶ ὑπὲρ αὐτῶν, εἰ δέοι, θνήσκειν ἡδέως."},{"number":43,"text":"ἤδη οὖν πολλοὶ πολλάκις ἑώρανται τῶν αἰχμαλώτων στρέβλας καὶ παντοίων θανάτων τρόπους ἐν θεάτροις ὑπομένοντες ἐπὶ τῷ μηδὲν ῥῆμα προέσθαι παρὰ τοὺς νόμους καὶ τὰς μετὰ τούτων ἀναγραφάς."},{"number":44,"text":"ὃ τίς ἂν ὑπομείνειεν Ἑλλήνων ὑπὲρ αὐτοῦ; ἀλλʼ οὐδʼ ὑπὲρ τοῦ καὶ πάντα τὰ παρʼ αὐτοῖς ἀφανισθῆναι συγγράμματα τὴν τυχοῦσαν ὑποστήσεται βλάβην·"},{"number":45,"text":"λόγους γὰρ αὐτὰ νομίζουσιν εἶναι κατὰ τὴν τῶν γραψάντων βούλησιν ἐσχεδιασμένους, καὶ τοῦτο δικαίως καὶ περὶ τῶν παλαιοτέρων φρονοῦσιν, ἐπειδὴ καὶ τῶν νῦν ἐνίους ὁρῶσι τολμῶντας περὶ τούτων συγγράφειν, οἷς μήτʼ αὐτοὶ παρεγένοντο μήτε πυθέσθαι παρὰ τῶν εἰδότων ἐφιλοτιμήθησαν."},{"number":46,"text":"ἀμέλει καὶ περὶ τοῦ γενομένου νῦν ἡμῖν πολέμου τινὲς ἱστορίας ἐπιγράψαντες ἐξενηνόχασιν οὔτʼ εἰς τοὺς τόπους παραβαλόντες οὔτε πλησίον τούτων πραττομένων προσελθόντες, ἀλλʼ ἐκ παρακουσμάτων ὀλίγα συνθέντες τῷ τῆς ἱστορίας ὀνόματι λίαν ἀναιδῶς ἐνεπαροίνησαν."},{"number":47,"text":"Ἐγὼ δὲ καὶ περὶ τοῦ πολέμου παντὸς καὶ περὶ τῶν αὐτῷ κατὰ μέρος γενομένων ἀληθῆ τὴν ἀναγραφὴν ἐποιησάμην τοῖς πράγμασιν αὐτὸς ἅπασι παρατυχών·"},{"number":48,"text":"ἐστρατήγουν μὲν γὰρ τῶν παρʼ ἡμῖν Γαλιλαίων ὀνομαζομένων ἕως ἀντέχειν δυνατὸν ἦν, ἐγενόμην δὲ παρὰ Ῥωμαίοις συλληφθεὶς αἰχμάλωτος καί με διὰ φυλακῆς Οὐεσπασιανὸς καὶ Τίτος ἔχοντες ἀεὶ προσεδρεύειν αὐτοῖς ἠνάγκασαν τὸ μὲν πρῶτον δεδεμένον, αὖθις δὲ λυθεὶς συνεπέμφθην ἀπὸ τῆς Ἀλεξανδρείας Τίτῳ πρὸς τὴν Ἱεροσολύμων πολιορκίαν."},{"number":49,"text":"ἐν ᾧ χρόνῳ γενομένην τῶν πραττομένων οὐκ ἔστιν ὃ τὴν ἐμὴν γνῶσιν διέφυγεν· καὶ γὰρ τὰ κατὰ τὸ στρατόπεδον τὸ Ῥωμαίων ὁρῶν ἐπιμελῶς ἀνέγραφον καὶ τὰ παρὰ τῶν αὐτομόλων ἀπαγγελλόμενα μόνος αὐτὸς συνίειν."},{"number":50,"text":"εἶτα σχολῆς ἐν τῇ Ῥώμῃ λαβόμενος, πάσης μοι τῆς πραγματείας ἐν παρασκευῇ γεγενημένης χρησάμενός τισι πρὸς τὴν Ἑλληνίδα φωνὴν συνεργοῖς οὕτως ἐποιησάμην τῶν πράξεων τὴν παράδοσιν. τοσοῦτον δέ μοι περιῆν θάρσος τῆς ἀληθείας, ὥστε πρώτους πάντων τοὺς αὐτοκράτορας τοῦ πολέμου γενομένους Οὐεσπασιανὸν καὶ Τίτον ἠξίωσα λαβεῖν μάρτυρας."},{"number":51,"text":"πρώτοις γὰρ δέδωκα τὰ βιβλία καὶ μετʼ ἐκείνους πολλοῖς μὲν Ῥωμαίων τοῖς συμπεπολεμηκόσι, πολλοῖς δὲ τῶν ἡμετέρων ἐπίπρασκον, ἀνδράσι καὶ τῆς Ἑλληνικῆς σοφίας μετεσχηκόσιν, ὧν ἐστιν Ἰούλιος Ἀρχέλαος, Ἡρώδης ὁ σεμνότατος, αὐτὸς ὁ θαυμασιώτατος βασιλεὺς Ἀγρίππας."},{"number":52,"text":"οὗτοι μὲν οὖν ἅπαντες ἐμαρτύρησαν, ὅτι τῆς ἀληθείας προύστην ἐπιμελῶς, οὐκ ἂν ὑποστειλάμενοι καὶ σιωπήσαντες, εἴ τι κατʼ ἄγνοιαν ἢ χαριζόμενος μετέθηκα τῶν γεγονότων ἢ παρέλιπον."},{"number":53,"text":"Φαῦλοι δέ τινες ἄνθρωποι διαβάλλειν μου τὴν ἱστορίαν ἐπικεχειρήκασιν ὥσπερ ἐν σχολῇ μειρακίων γύμνασμα προκεῖσθαι νομίζοντες κατηγορίας παραδόξου καὶ διαβολῆς, δέον ἐκεῖνο γιγνώσκειν, ὅτι δεῖ τὸν ἄλλοις παράδοσιν πράξεων ἀληθινῶν ὑπισχνούμενον αὐτὸν ἐπίστασθαι ταύτας πρότερον ἀκριβῶς ἢ παρηκολουθηκότα τοῖς γεγονόσιν ἢ παρὰ τῶν εἰδότων πυνθανόμενον."},{"number":54,"text":"ὅπερ ἐγὼ μάλιστα περὶ ἀμφοτέρας νομίζω πεποιηκέναι τὰς πραγματείας· τὴν μὲν γὰρ ἀρχαιολογίαν, ὥσπερ ἔφην, ἐκ τῶν ἱερῶν γραμμάτων μεθερμήνευκα γεγονὼς ἱερεὺς ἐκ γένους καὶ μετεσχηκὼς τῆς φιλοσοφίας τῆς ἐν ἐκείνοις τοῖς γράμμασι·"},{"number":55,"text":"τοῦ δὲ πολέμου τὴν ἱστορίαν ἔγραψα πολλῶν μὲν αὐτουργὸς πράξεων, πλείστων δʼ αὐτόπτης γενόμενος, ὅλως δὲ τῶν λεχθέντων ἢ πραχθέντων οὐδοτιοῦν ἀγνοήσας."},{"number":56,"text":"πῶς οὖν οὐκ ἂν θρασεῖς τις ἡγήσαιτο τοὺς ἀνταγωνίζεσθαί μοι περὶ τῆς ἀληθείας ἐπικεχειρηκότας, οἳ κἂν τοῖς τῶν αὐτοκρατόρων ὑπομνήμασιν ἐντυχεῖν λέγωσιν, ἀλλʼ οὔ γε καὶ τοῖς ἡμετέροις τῶν ἀντιπολεμούντων πράγμασι παρέτυχον."},{"number":57,"text":"Περὶ μὲν οὖν τούτων ἀναγκαίαν ἐποιησάμην τὴν παρέκβασιν ἐπισημήνασθαι βουλόμενος τῶν ἐπαγγελλομένων τὰς ἱστορίας συγγράφειν τὴν εὐχέρειαν."},{"number":58,"text":"ἱκανῶς δὲ φανερόν, ὡς οἶμαι, πεποιηκὼς ὅτι πάτριός ἐστιν ἡ περὶ τῶν παλαιῶν ἀναγραφὴ τοῖς βαρβάροις μᾶλλον ἢ τοῖς Ἕλλησι, βούλομαι μικρὰ πρότερον διαλεχθῆναι πρὸς τοὺς ἐπιχειροῦντας νέαν ἡμῶν ἀποφαίνειν τὴν κατάστασιν ἐκ τοῦ μηδὲν περὶ ἡμῶν, ὥς φασιν ἐκεῖνοι, λελέχθαι παρὰ τοῖς Ἑλληνικοῖς συγγραφεῦσιν."},{"number":59,"text":"εἶτα δὲ τὰς μαρτυρίας τῆς ἀρχαιότητος ἐκ τῶν παρʼ ἄλλοις γραμμάτων παρέξω καὶ τοὺς βεβλασφημηκότας ἡμῶν τὸ γένος ἀποδείξω λίαν ἐν τοῖς λόγοις βλασφημοῦντας."},{"number":60,"text":"Ἡμεῖς τοίνυν οὔτε χώραν οἰκοῦμεν παράλιον οὔτʼ ἐμπορίαις χαίρομεν οὐδὲ ταῖς πρὸς ἄλλους διὰ τούτων ἐπιμιξίαις, ἀλλʼ εἰσὶ μὲν ἡμῶν αἱ πόλεις μακρὰν ἀπὸ θαλάσσης ἀνῳκισμέναι, χώραν δὲ ἀγαθὴν νεμόμενοι ταύτην ἐκπονοῦμεν μάλιστα δὴ πάντων περὶ παιδοτροφίαν φιλοκαλοῦντες καὶ τὸ φυλάττειν τοὺς νόμους καὶ τὴν κατὰ τούτους παραδεδομένην εὐσέβειαν ἔργον ἀναγκαιότατον παντὸς τοῦ βίου πεποιημένοι."},{"number":61,"text":"προσούσης τοίνυν τοῖς εἰρημένοις καὶ τῆς περὶ τὸν βίον ἡμῶν ἰδιότητος οὐδὲν ἐν τοῖς παλαιοῖς χρόνοις ποιοῦν ἡμῖν πρὸς τοὺς Ἕλληνας ἐπιμιξίαν, ὥσπερ Αἰγυπτίοις μὲν τὰ παρʼ αὐτῶν ἐξαγόμενα καὶ πρὸς αὐτοὺς εἰσαγόμενα, τοῖς δὲ τὴν παράλιον τῆς Φοινίκης κατοικοῦσιν ἡ περὶ τὰς καπηλείας καὶ περὶ τὰς ἐμπορίας σπουδὴ διὰ τὸ φιλοχρηματεῖν."},{"number":62,"text":"οὐ μὴν οὐδὲ πρὸς λῃστείας, ὥσπερ ἄλλοι τινές, ἢ τὸ πλέον ἔχειν ἀξιοῦν πολεμοῦντες ἐτράπησαν ἡμῶν οἱ πατέρες καίτοι πολλὰς τῆς χώρας ἐχούσης μυριάδας ἀνδρῶν οὐκ ἀτόλμων."},{"number":63,"text":"διὰ τοῦτο Φοίνικες μὲν αὐτοὶ κατʼ ἐμπορίαν τοῖς Ἕλλησιν ἐπεισπλέοντες εὐθὺς ἐγνώσθησαν καὶ διʼ ἐκείνων Αἰγύπτιοι καὶ πάντες, ἀφʼ ὧν τὸν φόρτον εἰς τοὺς Ἕλληνας διεκόμιζον μεγάλα πελάγη διαίροντες."},{"number":64,"text":"Μῆδοι δὲ μετὰ ταῦτα καὶ Πέρσαι φανεροὶ κατέστησαν τῆς Ἀσίας ἐπάρξαντες, οἱ δὲ καὶ μέχρι τῆς ἡμετέρας ἠπείρου Πέρσαι στρατεύσαντες. Θρᾷκες δὲ διὰ γειτονίαν καὶ τὸ Σκυθικὸν ὑπὸ τῶν εἰς τὸν Πόντον ἐγνώσθη πλεόντων."},{"number":65,"text":"ὅλως γὰρ ἅπαντες οἱ παρὰ τὴν θάλατταν καὶ τὴν πρὸς ταῖς ἀνατολαῖς καὶ πρὸς τὴν ἑσπέριον κατοικοῦντες τοῖς συγγράφειν τι βουλομένοις γνωριμώτεροι κατέστησαν, οἱ δὲ ταύτης ἀνωτέρω τὰς οἰκήσεις ἔχοντες ἐπὶ πλεῖστον ἠγνοήθησαν."},{"number":66,"text":"καὶ τοῦτο φαίνεται καὶ περὶ τὴν Εὐρώπην συμβεβηκός, ὅπου γε τῆς Ῥωμαίων πόλεως, τοιαύτην ἐκ μακροῦ δύναμιν κεκτημένης καὶ τοιαύτας πράξεις κατορθούσης πολεμικάς, οὔθʼ ὁ Ἡρόδοτος οὔτε Θουκυδίδης οὔτε τῶν ἅμα τούτοις γενομένων οὐδὲ εἷς ἐμνημόνευκεν, ἀλλʼ ὀψέ ποτε καὶ μόλις αὐτῶν εἰς τοὺς Ἕλληνας ἡ γνῶσις διεξῆλθεν."},{"number":67,"text":"περὶ μὲν γὰρ Γαλατῶν τε καὶ Ἰβήρων οὕτως ἠγνόησαν οἱ δοκοῦντες ἀκριβέστατοι συγγραφεῖς, ὧν ἐστιν Ἔφορος, ὥστε πόλιν οἴεται μίαν εἶναι τοὺς Ἴβηρας τοὺς τοσοῦτο μέρος τῆς ἑσπερίου γῆς κατοικοῦντας, καὶ τὰ μήτε γενόμενα παρʼ αὐτοῖς ἔθη μήτε λεγόμενα γράφειν ὡς ἐκείνων αὐτοῖς χρωμένων ἐτόλμησαν."},{"number":68,"text":"αἴτιον δὲ τοῦ μὲν μὴ γιγνώσκειν τἀληθὲς τὸ λίαν ἀνεπίμικτον, τοῦ δὲ γράφειν ψευδῆ τὸ βούλεσθαι δοκεῖν τι πλέον τῶν ἄλλων ἱστορεῖν. πῶς οὖν ἔτι θαυμάζειν προσῆκεν, εἰ μηδὲ τὸ ἡμέτερον ἔθνος πολλοῖς ἐγιγνώσκετο μηδὲ τῆς ἐν τοῖς συγγράμμασι μνήμης ἀφορμὴν παρέσχεν, οὕτως μὲν ἀπῳκισμένον τῆς θαλάσσης, οὕτως δὲ βιοτεύειν προῃρημένον;"},{"number":69,"text":"Φέρε τοίνυν ἡμᾶς ἀξιοῦν τεκμηρίῳ χρῆσθαι περὶ τῶν Ἑλλήνων, ὅτι μὴ παλαιόν ἐστιν αὐτῶν τὸ γένος, τῷ μηθὲν ἐν ταῖς ἡμετέραις ἀναγραφαῖς περὶ αὐτῶν εἰρῆσθαι. ἆρʼ οὐχὶ πάντως ἂν κατεγέλων αὐτὰς οἶμαι τὰς ὑπʼ ἐμοῦ νῦν εἰρημένας κομίζοντες αἰτίας καὶ μάρτυρας ἂν τοὺς πλησιοχώρους παρείχοντο τῆς αὐτῶν ἀρχαιότητος;"},{"number":70,"text":"κἀγὼ τοίνυν πειράσομαι τοῦτο ποιεῖν· Αἰγυπτίοις γὰρ καὶ Φοίνιξι μάλιστα δὴ χρήσομαι μάρτυσιν, οὐκ ἄν τινος ὡς ψευδῆ τὴν μαρτυρίαν διαβάλλειν δυνηθέντος· φαίνονται γὰρ καὶ δὴ μάλιστα πρὸς ἡμᾶς δυσμενῶς διατεθέντες κοινῇ μὲν ἅπαντες Αἰγύπτιοι, Φοινίκων δὲ Τύριοι."},{"number":71,"text":"περὶ μέντοι Χαλδαίων οὐκέτι ταὐτὸ τοῦτο δυναίμην ἂν λέγειν, ἐπεὶ καὶ τοῦ γένους ἡμῶν ἀρχηγοὶ καθεστήκασιν καὶ διὰ τὴν συγγένειαν ἐν ταῖς αὐτῶν ἀναγραφαῖς Ἰουδαίων μνημονεύουσιν."},{"number":72,"text":"ὅταν δὲ τὰς περὶ τούτων πίστεις παράσχω, τότε καὶ τῶν Ἑλλήνων συγγραφέων ἀποφανῶ τοὺς μνήμην Ἰουδαίων πεποιηκότας, ἵνα μηδὲ ταύτην ἔτι τὴν πρόφασιν οἱ βασκαίνοντες ἔχωσιν τῆς πρὸς ἡμᾶς ἀντιλογίας."},{"number":73,"text":"Ἄρξομαι δὲ πρῶτον ἀπὸ τῶν παρʼ Αἰγυπτίοις γραμμάτων. αὐτὰ μὲν οὖν οὐχ οἷόν τε παρατίθεσθαι τἀκείνων, Μάνεθως δʼ ἦν τὸ γένος Αἰγύπτιος ἀνὴρ τῆς Ἑλληνικῆς μετεσχηκὼς παιδείας, ὡς δῆλός ἐστιν· γέγραφεν γὰρ Ἑλλάδι φωνῇ τὴν πάτριον ἱστορίαν ἔκ τε τῶν ἱερῶν, ὥς φησιν αὐτός, μεταφράσας καὶ πολλὰ τὸν Ἡρόδοτον ἐλέγχει τῶν Αἰγυπτιακῶν ὑπʼ ἀγνοίας ἐψευσμένον."},{"number":74,"text":"οὗτος δὴ τοίνυν ὁ Μάνεθως ἐν τῇ δευτέρᾳ τῶν Αἰγυπτιακῶν ταῦτα περὶ ἡμῶν γράφει. παραθήσομαι δὲ τὴν λέξιν αὐτοῦ καθάπερ αὐτὸν ἐκεῖνον παραγαγὼν μάρτυρα·"},{"number":75,"text":"τοῦ τίμαιος ὄνομα. ἐπὶ τούτου οὐκ οἶδʼ ὅπως θεὸς ἀντέπνευσεν καὶ παραδόξως ἐκ τῶν πρὸς ἀνατολὴν μερῶν ἄνθρωποι τὸ γένος ἄσημοι καταθαρρήσαντες ἐπὶ τὴν χώραν ἐστράτευσαν καὶ ῥᾳδίως ἀμαχητὶ ταύτην κατὰ κράτος εἷλον,"},{"number":76,"text":"καὶ τοὺς ἡγεμονεύσαντας ἐν αὐτῇ χειρωσάμενοι τὸ λοιπὸν τάς τε πόλεις ὠμῶς ἐνέπρησαν καὶ τὰ τῶν θεῶν ἱερὰ κατέσκαψαν, πᾶσι δὲ τοῖς ἐπιχωρίοις ἐχθρότατά πως ἐχρήσαντο τοὺς μὲν σφάζοντες, τῶν δὲ καὶ τὰ τέκνα καὶ γυναῖκας εἰς δουλείαν ἄγοντες."},{"number":77,"text":"πέρας δὲ καὶ βασιλέα ἕνα ἐξ αὐτῶν ἐποίησαν, ᾧ ὄνομα ἦν Σάλιτις. καὶ οὗτος ἐν τῇ Μέμφιδι κατεγίνετο τήν τε ἄνω καὶ κάτω χώραν δασμολογῶν καὶ φρουρὰν ἐν τοῖς ἐπιτηδειοτάτοις καταλιπὼν τόποις. μάλιστα δὲ καὶ τὰ πρὸς ἀνατολὴν ἠσφαλίσατο μέρη προορώμενος Ἀσσυρίων ποτὲ μεῖζον ἰσχυόντων ἐσομένην ἐπιθυμίᾳ τῆς αὐτοῦ βασιλείας ἔφοδον."},{"number":78,"text":"εὑρὼν δὲ ἐν νομῷ τῷ Σεθροΐτῃ πόλιν ἐπικαιροτάτην, κειμένην μὲν πρὸς ἀνατολὴν τοῦ Βουβαστίτου ποταμοῦ, καλουμένην δʼ ἀπό τινος ἀρχαίας θεολογίας Αὔαριν, ταύτην ἔκτισέν τε καὶ τοῖς τείχεσιν ὀχυρωτάτην ἐποίησεν ἐνοικίσας αὐτῇ καὶ πλῆθος ὁπλιτῶν εἰς εἴκοσι καὶ τέσσαρας μυριάδας ἀνδρῶν προφυλακήν."},{"number":79,"text":"ἔνθα δὲ κατὰ θέρειαν ἤρχετο τὰ μὲν σιτομετρῶν καὶ μισθοφορίαν παρεχόμενος τὰ δὲ καὶ ταῖς ἐξοπλισίαις πρὸς φόβον τῶν ἔξωθεν ἐπιμελῶς γυμνάζων. ἄρξας δʼ ἐννεακαίδεκα ἔτη τὸν βίον ἐτελεύτησε."},{"number":80,"text":"μετὰ τοῦτον δὲ ἕτερος ἐβασίλευσεν τέσσαρα καὶ τεσσαράκοντα ἔτη καλούμενος Βηών. μεθʼ ὃν ἄλλος Ἀπαχνὰς ἓξ καὶ τριάκοντα ἔτη καὶ μῆνας ἑπτά. ἔπειτα δὲ καὶ Ἄπωφις ἓν καὶ ἑξήκοντα καὶ Ἰαννὰς πεντήκοντα καὶ μῆνα ἕνα."},{"number":81,"text":"ἐπὶ πᾶσι δὲ καὶ Ἄσσις ἐννέα καὶ τεσσαράκοντα καὶ μῆνας δύο. καὶ οὗτοι μὲν ἓξ ἐν αὐτοῖς ἐγενήθησαν πρῶτοι ἄρχοντες ποθοῦντες ἀεὶ καὶ μᾶλλον τῆς Αἰγύπτου ἐξᾶραι τὴν ῥίζαν."},{"number":82,"text":"ἐκαλεῖτο δὲ τὸ σύμπαν αὐτῶν ἔθνος Ὑκσώς, τοῦτο δέ ἐστιν βασιλεῖς ποιμένες· τὸ γὰρ υκ καθʼ ἱερὰν γλῶσσαν βασιλέα σημαίνει, τὸ δὲ σὼς ποιμήν ἐστι καὶ ποιμένες κατὰ τὴν κοινὴν διάλεκτον, καὶ οὕτως συντιθέμενον γίνεται Ὑκσώς."},{"number":83,"text":"τινὲς δὲ λέγουσιν αὐτοὺς Ἄραβας εἶναι. ἐν δʼ ἄλλῳ ἀντιγράφῳ οὐ βασιλεῖς σημαίνεσθαι διὰ τῆς ϋκ προσηγορίας, ἀλλὰ τοὐναντίον αἰχμαλώτους δηλοῦσθαι ποιμένας· τὸ γὰρ ὓκ πάλιν Αἰγυπτιστὶ καὶ τὸ ἃκ δασυνόμενον αἰχμαλώτους ῥητῶς μηνύει. καὶ τοῦτο μᾶλλον πιθανώτερόν μοι φαίνεται καὶ παλαιᾶς ἱστορίας ἐχόμενον."},{"number":84,"text":"τούτους τοὺς προκατωνομασμένους βασιλέας καὶ τοὺς τῶν ποιμένων καλουμένων καὶ τοὺς ἐξ αὐτῶν γενομένους κρατῆσαι τῆς Αἰγύπτου φησὶν ἔτη πρὸς τοῖς πεντακοσίοις ἕνδεκα."},{"number":85,"text":"μετὰ ταῦτα δὲ τῶν ἐκ τῆς Θηβαΐδος καὶ τῆς ἄλλης Αἰγύπτου βασιλέων γενέσθαι φησὶν ἐπὶ τοὺς ποιμένας ἐπανάστασιν καὶ πόλεμον συρραγῆναι μέγαν καὶ πολυχρόνιον."},{"number":86,"text":"ἐπὶ δὲ βασιλέως, ᾧ ὄνομα εἶναι Μισφραγμούθωσις, ἡττωμένους φησὶ τοὺς ποιμένας ἐκ μὲν τῆς ἄλλης Αἰγύπτου πάσης ἐκπεσεῖν, κατακλεισθῆναι δʼ εἰς τόπον ἀρουρῶν ἔχοντα μυρίων τὴν περίμετρον· Αὔαριν ὄνομα τῷ τόπῳ."},{"number":87,"text":"τοῦτόν φησιν ὁ Μάνεθως ἅπαντα τείχει τε μεγάλῳ καὶ ἰσχυρῷ περιβαλεῖν τοὺς ποιμένας, ὅπως τήν τε κτῆσιν ἅπασαν ἔχωσιν ἐν ὀχυρῷ καὶ τὴν λείαν τὴν ἑαυτῶν."},{"number":88,"text":"τὸν δὲ Μισφραγμουθώσεως υἱὸν Θούμμωσιν ἐπιχειρῆσαι μὲν αὐτοὺς διὰ πολιορκίας ἑλεῖν κατὰ κράτος ὀκτὼ καὶ τεσσαράκοντα μυριάσι στρατοῦ προσεδρεύσαντα τοῖς τείχεσιν· ἐπεὶ δὲ τὴν πολιορκίαν ἀπέγνω, ποιήσασθαι συμβάσεις, ἵνα τὴν Αἴγυπτον ἐκλιπόντες ὅποι βούλονται πάντες ἀβλαβεῖς ἀπέλθωσι."},{"number":89,"text":"τοὺς δὲ ἐπὶ ταῖς ὁμολογίαις πανοικησίᾳ μετὰ τῶν κτήσεων οὐκ ἐλάττους μυριάδων ὄντας εἴκοσι καὶ τεσσάρων ἀπὸ τῆς Αἰγύπτου τὴν ἔρημον εἰς Συρίαν διοδοιπορῆσαι."},{"number":90,"text":"φοβουμένους δὲ τὴν Ἀσσυρίων δυναστείαν, τότε γὰρ ἐκείνους τῆς Ἀσίας κρατεῖν, ἐν τῇ νῦν Ἰουδαίᾳ καλουμένῃ πόλιν οἰκοδομησαμένους τοσαύταις μυριάσιν ἀνθρώπων ἀρκέσουσαν Ἱεροσόλυμα ταύτην ὀνομάσαι."},{"number":91,"text":"ἐν ἄλλῃ δέ τινι βίβλῳ τῶν Αἰγυπτιακῶν Μάνεθως τοῦτό φησιν τὸ ἔθνος τοὺς καλουμένους ποιμένας αἰχμαλώτους ἐν ταῖς ἱεραῖς αὐτῶν βίβλοις γεγράφθαι λέγων ὀρθῶς· καὶ γὰρ τοῖς ἀνωτάτω προγόνοις ἡμῶν τὸ ποιμαίνειν πάτριον ἦν καὶ νομαδικὸν ἔχοντες τὸν βίον οὕτως ἐκαλοῦντο ποιμένες."},{"number":92,"text":"αἰχμάλωτοί τε πάλιν οὐκ ἀλόγως ὑπὸ τῶν Αἰγυπτίων ἀνεγράφησαν, ἐπειδήπερ ὁ πρόγονος ἡμῶν Ἰώσηπος ἑαυτὸν ἔφη πρὸς τὸν βασιλέα τῶν Αἰγυπτίων αἰχμάλωτον εἶναι, καὶ τοὺς ἀδελφοὺς εἰς τὴν Αἴγυπτον ὕστερον μετεπέμψατο τοῦ βασιλέως ἐπιτρέψαντος. ἀλλὰ περὶ μὲν τούτων ἐν ἄλλοις ποιήσομαι τὴν ἐξέτασιν ἀκριβεστέραν."},{"number":93,"text":"Νυνὶ δὲ τῆς ἀρχαιότητος ταύτης παρατίθεμαι τοὺς Αἰγυπτίους μάρτυρας. πάλιν οὖν τὰ τοῦ Μανέθω πῶς ἔχει πρὸς τὴν τῶν χρόνων τάξιν ὑπογράψω."},{"number":94,"text":"φησὶ δὲ οὕτως· μετὰ τὸ ἐξελθεῖν ἐξ Αἰγύπτου τὸν λαὸν τῶν ποιμένων εἰς Ἱεροσόλυμα ὁ ἐκβαλὼν αὐτοὺς ἐξ Αἰγύπτου βασιλεὺς Τέθμωσις ἐβασίλευσεν μετὰ ταῦτα ἔτη εἰκοσιπέντε καὶ μῆνας τέσσαρας καὶ ἐτελεύτησεν, καὶ παρέλαβεν τὴν ἀρχὴν ὁ αὐτοῦ υἱὸς Χέβρων ἔτη δεκατρία."},{"number":95,"text":"μεθʼ ὃν Ἀμένωφις εἴκοσι καὶ μῆνας ἑπτά. τοῦ δὲ ἀδελφὴ Ἀμεσσὴς εἰκοσιὲν καὶ μῆνας ἐννέα. τῆς δὲ Μήφρης δώδεκα καὶ μῆνας ἐννέα. τοῦ δὲ Μηφραμούθωσις εἰκοσιπέντε καὶ μῆνας δέκα."},{"number":96,"text":"τοῦ δὲ Θμῶσις ἐννέα καὶ μῆνας ὀκτώ. τοῦ δʼ Ἀμένωφις τριάκοντα καὶ μῆνας δέκα. τοῦ δὲ Ὦρος τριακονταὲξ καὶ μῆνας πέντε. τοῦ δὲ θυγάτηρ Ἀκεγχερὴς δώδεκα καὶ μῆνα ἕνα. τῆς δὲ Ῥάθωτις ἀδελφὸς ἐννέα."},{"number":97,"text":"τοῦ δὲ Ἀκεγχήρης δώδεκα καὶ μῆνας πέντε. τοῦ δὲ Ἀκεγχήρης ἕτερος δώδεκα καὶ μῆνας τρεῖς. τοῦ δὲ Ἅρμαϊς τέσσαρα καὶ μῆνα ἕνα. τοῦ δὲ Ῥαμέσσης ἓν καὶ μῆνας τέσσαρας. τοῦ δὲ Ἁρμέσσης Μιαμοῦν ἑξηκονταὲξ καὶ μῆνας δύο."},{"number":98,"text":"τοῦ δὲ Ἀμένωφις δεκαεννέα καὶ μῆνας ἕξ. τοῦ δὲ Σέθως ὁ καὶ Ῥαμέσσης ἱππικὴν καὶ ναυτικὴν ἔχων δύναμιν τὸν μὲν ἀδελφὸν Ἅρμαϊν ἐπίτροπον τῆς Αἰγύπτου κατέστησεν καὶ πᾶσαν μὲν αὐτῷ τὴν ἄλλην βασιλικὴν περιέθηκεν ἐξουσίαν, μόνον δὲ ἐνετείλατο διάδημα μὴ φορεῖν μηδὲ τὴν βασιλίδα μητέρα τε τῶν τέκνων ἀδικεῖν, ἀπέχεσθαι δὲ καὶ τῶν ἄλλων βασιλικῶν παλλακίδων."},{"number":99,"text":"αὐτὸς δὲ ἐπὶ Κύπρον καὶ Φοινίκην καὶ πάλιν Ἀσσυρίους τε καὶ Μήδους στρατεύσας ἅπαντας τοὺς μὲν δόρατι, τοὺς δὲ ἀμαχητὶ φόβῳ δὲ τῆς πολλῆς δυνάμεως ὑποχειρίους ἔλαβε καὶ μέγα φρονήσας ἐπὶ ταῖς εὐπραγίαις ἔτι καὶ θαρσαλεώτερον ἐπεπορεύετο τὰς πρὸς ἀνατολὰς πόλεις τε καὶ χώρας καταστρεφόμενος."},{"number":100,"text":"χρόνου τε ἱκανοῦ γεγονότος Ἅρμαϊς ὁ καταλειφθεὶς ἐν Αἰγύπτῳ πάντα τἄμπαλιν οἷς ἀδελφὸς παρῄνει μὴ ποιεῖν ἀδεῶς ἔπραττεν· καὶ γὰρ τὴν βασιλίδα βιαίως ἔσχεν καὶ ταῖς ἄλλαις παλλακίσιν ἀφειδῶς διετέλει χρώμενος, πειθόμενος δὲ ὑπὸ τῶν φίλων διάδημα ἐφόρει καὶ ἀντῆρε τῷ ἀδελφῷ."},{"number":101,"text":"ὁ δὲ τεταγμένος ἐπὶ τῶν ἱερέων τῆς Αἰγύπτου γράψας βιβλίον ἔπεμψε τῷ Σεθώσει δηλῶν αὐτῷ πάντα καὶ ὅτι ἀντῆρεν ὁ ἀδελφὸς αὐτοῦ Ἅρμαϊς. παραχρῆμα οὖν ὑπέστρεψεν εἰς Πηλούσιον καὶ ἐκράτησεν τῆς ἰδίας βασιλείας."},{"number":102,"text":"ἡ δὲ χώρα ἐκλήθη ἀπὸ τοῦ αὐτοῦ ὀνόματος Αἴγυπτος· λέγει γάρ, ὅτι ὁ μὲν Σέθως ἐκαλεῖτο Αἴγυπτος, Ἅρμαϊς δὲ ὁ ἀδελφὸς αὐτοῦ Δαναός."},{"number":103,"text":"Ταῦτα μὲν ὁ Μάνεθως. δῆλον δέ ἐστιν ἐκ τῶν εἰρημένων ἐτῶν τοῦ χρόνου συλλογισθέντος, ὅτι οἱ καλούμενοι ποιμένες ἡμέτεροι δὲ πρόγονοι τρισὶ καὶ ἐνενήκοντα καὶ τριακοσίοις πρόσθεν ἔτεσιν ἐκ τῆς Αἰγύπτου ἀπαλλαγέντες τὴν χώραν ταύτην ἐπῴκησαν ἢ Δαναὸν εἰς Ἄργος ἀφικέσθαι· καίτοι τοῦτον ἀρχαιότατον Ἀργεῖοι νομίζουσι."},{"number":104,"text":"δύο τοίνυν ὁ Μάνεθως ἡμῖν τὰ μέγιστα μεμαρτύρηκεν ἐκ τῶν παρʼ Αἰγυπτίοις γραμμάτων, πρῶτον μὲν τὴν ἑτέρωθεν ἄφιξιν εἰς Αἴγυπτον, ἔπειτα δὲ τὴν ἐκεῖθεν ἀπαλλαγὴν οὕτως ἀρχαίαν τοῖς χρόνοις, ὡς ἐγγύς που προτερεῖν αὐτὴν τῶν Ἰλιακῶν ἔτεσι χιλίοις."},{"number":105,"text":"ὑπὲρ ὧν δʼ ὁ Μάνεθως οὐκ ἐκ τῶν παρʼ Αἰγυπτίοις γραμμάτων, ἀλλʼ ὡς αὐτὸς ὡμολόγηκεν ἐκ τῶν ἀδεσπότως μυθολογουμένων προστέθεικεν, ὕστερον ἐξελέγξω κατὰ μέρος ἀποδεικνὺς τὴν ἀπίθανον αὐτοῦ ψευδολογίαν."},{"number":106,"text":"Βούλομαι τοίνυν ἀπὸ τούτων ἤδη μετελθεῖν ἐπὶ τὰ παρὰ τοῖς Φοίνιξιν ἀναγεγραμμένα περὶ τοῦ γένους ἡμῶν καὶ τὰς ἐξ ἐκείνων μαρτυρίας παρασχεῖν."},{"number":107,"text":"ἔστι τοίνυν παρὰ Τυρίοις ἀπὸ παμπόλλων ἐτῶν γράμματα δημοσίᾳ γεγραμμένα καὶ πεφυλαγμένα λίαν ἐπιμελῶς περὶ τῶν παρʼ αὐτοῖς γενομένων καὶ πρὸς ἀλλήλους πραχθέντων μνήμης ἀξίων."},{"number":108,"text":"ἐν οἷς γέγραπται, ὅτι ὁ ἐν Ἱεροσολύμοις ᾠκοδομήθη ναὸς ὑπὸ Σολομῶνος τοῦ βασιλέως ἔτεσι θᾶττον ἑκατὸν τεσσαρακοντατρισὶν καὶ μησὶν ὀκτὼ τοῦ κτίσαι Τυρίους Καρχηδόνα."},{"number":109,"text":"ἀνεγράφη δὲ παρʼ ἐκείνοις οὐκ ἀλόγως ἡ τοῦ ναοῦ κατασκευὴ τοῦ παρʼ ἡμῖν· Εἴρωμος γὰρ ὁ τῶν Τυρίων βασιλεὺς φίλος ἦν τοῦ βασιλέως ἡμῶν Σολομῶνος πατρικὴν πρὸς αὐτὸν φιλίαν διαδεδεγμένος."},{"number":110,"text":"οὗτος οὖν συμφιλοτιμούμενος εἰς τὴν τοῦ κατασκευάσματος τῷ Σολομῶνι λαμπρότητα χρυσίου μὲν εἴκοσι καὶ ἑκατὸν ἔδωκε τάλαντα, τεμὼν δὲ καλλίστην ὕλην ἐκ τοῦ ὄρους, ὃ καλεῖται Λίβανος, εἰς τὸν ὄροφον ἀπέστειλεν. ἀντεδωρήσατο δὲ αὐτῷ ὁ Σολομὼν ἄλλοις τε πολλοῖς καὶ δὴ καὶ χώραν τῆς Γαλιλαίας ἐν τῇ Χαβουλῶν λεγομένῃ."},{"number":111,"text":"μάλιστα δὲ αὐτοὺς εἰς φιλίαν ἡ τῆς σοφίας συνῆγεν ἐπιθυμία· προβλήματα γὰρ ἀλλήλοις ἀνταπέστελλον λύειν κελεύοντες, καὶ κρείττων ἐν τούτοις ἦν ὁ Σολομὼν καὶ τἆλλα σοφώτερος. σώζονται δὲ μέχρι νῦν παρὰ τοῖς Τυρίοις πολλαὶ τῶν ἐπιστολῶν, ἃς ἐκεῖνοι πρὸς ἀλλήλους ἔγραψαν."},{"number":112,"text":"ὅτι δʼ οὐ λόγος ἐστὶν ὑπʼ ἐμοῦ συγκείμενος ὁ περὶ τῶν παρὰ τοῖς Τυρίοις γραμμάτων, παραθήσομαι μάρτυρα Δῖον ἄνδρα περὶ τὴν Φοινικικὴν ἱστορίαν ἀκριβῆ γεγονέναι πεπιστευμένον. οὗτος τοίνυν ἐν ταῖς περὶ Φοινίκων ἱστορίαις γράφει τὸν τρόπον τοῦτον·"},{"number":113,"text":"Ἀβιβάλου τελευτήσαντος ὁ υἱὸς αὐτοῦ Εἴρωμος ἐβασίλευσεν. οὗτος τὰ πρὸς ἀνατολὰς μέρη τῆς πόλεως προσέχωσεν καὶ μεῖζον τὸ ἄστυ ἐποίησεν καὶ τοῦ Ὀλυμπίου Διὸς τὸ ἱερὸν καθʼ ἑαυτὸ ὂν ἐν νήσῳ χώσας τὸν μεταξὺ τόπον συνῆψε τῇ πόλει καὶ χρυσοῖς ἀναθήμασιν ἐκόσμησεν, ἀναβὰς δὲ εἰς τὸν Λίβανον ὑλοτόμησεν πρὸς τὴν τῶν ἱερῶν κατασκευήν."},{"number":114,"text":"τὸν δὲ τυραννοῦντα Ἱεροσολύμων Σολομῶνα πέμψαι φασὶ πρὸς τὸν Εἴρωμον αἰνίγματα καὶ παρʼ αὐτοῦ λαβεῖν ἀξιοῦν, τὸν δὲ μὴ δυνηθέντα διακρῖναι τῷ λύσαντι χρήματα ἀποτίνειν."},{"number":115,"text":"ὁμολογήσαντα δὲ τὸν Εἴρωμον καὶ μὴ δυνηθέντα λῦσαι τὰ αἰνίγματα πολλὰ τῶν χρημάτων εἰς τὸ ἐπιζήμιον ἀναλῶσαι. εἶτα δὲ Ἀβδήμουνόν τινα Τύριον ἄνδρα τά τε προτεθέντα λῦσαι καὶ αὐτὸν ἄλλα προβαλεῖν, ἃ μὴ λύσαντα τὸν Σολομῶνα πολλὰ τῷ Εἰρώμῳ προσαποτῖσαι χρήματα. Δῖος μὲν οὕτω περὶ τῶν προειρημένων ἡμῖν μεμαρτύρηκεν."},{"number":116,"text":"Ἀλλὰ πρὸς τούτῳ παραθήσομαι καὶ Μένανδρον τὸν Ἐφέσιον. γέγραφεν δὲ οὗτος τὰς ἐφʼ ἑκάστου τῶν βασιλέων πράξεις τὰς παρὰ τοῖς Ἕλλησι καὶ βαρβάροις γενομένας ἐκ τῶν παρʼ ἑκάστοις ἐπιχωρίων γραμμάτων σπουδάσας τὴν ἱστορίαν μαθεῖν."},{"number":117,"text":"γράφων τοίνυν περὶ τῶν ἐν Τύρῳ βεβασιλευκότων ἔπειτα γενόμενος κατὰ τὸν Εἴρωμον ταῦτά φησι· τελευτήσαντος δὲ Ἀβιβάλου διεδέξατο τὴν βασιλείαν αὐτοῦ ὁ υἱὸς Εἴρωμος, ὃς βιώσας ἔτη νγ ἐβασίλευσεν ἔτη λδ."},{"number":118,"text":"οὗτος ἔχωσε τὸν Εὐρύχωρον τόν τε χρυσοῦν κίονα τὸν ἐν τοῖς τοῦ Διὸς ἀνέθηκεν, ἐπί τε ὕλην ξύλων ἀπελθὼν ἔκοψεν ἀπὸ τοῦ λεγομένου Λιβάνου ὄρους κέδρινα ξύλα εἰς τὰς τῶν ἱερῶν στέγας, καθελών τε τὰ ἀρχαῖα ἱερὰ καὶ ναοὺς ᾠκοδόμησεν τό τε τοῦ Ἡρακλέους καὶ τῆς Ἀστάρτης,"},{"number":119,"text":"πρῶτόν τε τοῦ Ἡρακλέους ἔγερσιν ἐποιήσατο ἐν τῷ Περιτίῳ μηνί, τοῖς τε Ἰτυκαίοις ἐπεστρατεύσατο μὴ ἀποδιδοῦσι τοὺς φόρους· οὓς καὶ ὑποτάξας ἑαυτῷ πάλιν ἀνέστρεψεν."},{"number":120,"text":"ἐπὶ τούτου ἦν Ἀβδήμουνος παῖς νεώτερος, ὃς ἀεὶ ἐνίκα τὰ προβλήματα, ἃ ἐπέταττε Σολομὼν ὁ Ἱεροσολύμων βασιλεύς."},{"number":121,"text":"ψηφίζεται δὲ ὁ χρόνος ἀπὸ τούτου τοῦ βασιλέως ἄχρι Καρχηδόνος κτίσεως οὕτως· τελευτήσαντος Εἰρώμου διεδέξατο τὴν βασιλείαν Βαλβάζερος υἱός, ὃς βιώσας ἔτη μγ ἐβασίλευσεν ἔτη ιζ."},{"number":122,"text":"μετὰ τοῦτον Ἀβδάσταρτος υἱὸς βιώσας ἔτη λθ ἐβασίλευσεν ἔτη θ. τοῦτον οἱ τῆς τροφοῦ αὐτοῦ υἱοὶ τέσσαρες ἐπιβουλεύσαντες ἀπώλεσαν, ὧν ὁ πρεσβύτερος ἐβασίλευσεν Μεθουσάσταρτος ὁ Λεαστάρτου, ὃς βιώσας ἔτη νδ ἐβασίλευσεν ἔτη ιβ."},{"number":123,"text":"μετὰ τοῦτον ὁ ἀδελφὸς αὐτοῦ Ἀσθάρυμος βιώσας ἔτη νη ἐβασίλευσεν ἔτη θ. οὗτος ἀπώλετο ὑπὸ τοῦ ἀδελφοῦ Φέλλητος, ὃς λαβὼν τὴν βασιλείαν ἦρξεν μῆνας η βιώσας ἔτη ν. τοῦτον ἀνεῖλεν Εἰθώβαλος ὁ τῆς Ἀστάρτης ἱερεύς, ὃς βιώσας ἔτη μη ἐβασίλευσεν ἔτη λβ."},{"number":124,"text":"τοῦτον διεδέξατο Βαλέζωρος υἱός, ὃς βιώσας ἔτη με ἐβασίλευσεν ἔτη ἕξ."},{"number":125,"text":"τούτου διάδοχος γέγονε Μέττηνος υἱός, ὃς βιώσας ἔτη λβ ἐβασίλευσεν ἔτη κθ. τούτου διάδοχος γέγονεν Πυγμαλίων, ὃς βιώσας ἔτη νη ἐβασίλευσεν ἔτη μζ. ἐν δὲ τῷ ἐπʼ αὐτοῦ ἑβδόμῳ ἔτει ἡ ἀδελφὴ αὐτοῦ φυγοῦσα ἐν τῇ Λιβύῃ πόλιν ᾠκοδόμησεν Καρχηδόνα."},{"number":126,"text":"συνάγεται πᾶς ὁ χρόνος ἀπὸ τῆς Εἰρώμου βασιλείας μέχρι Καρχηδόνος κτίσεως ἔτη ρνε μῆνες η. ἐπεὶ δὲ δωδεκάτῳ ἔτει τῆς αὐτοῦ βασιλείας ὁ ἐν Ἱεροσολύμοις ᾠκοδομήθη ναός, γέγονεν ἀπὸ τῆς οἰκοδομήσεως τοῦ ναοῦ μέχρι Καρχηδόνος κτίσεως ἔτη ρμγ μῆνες η."},{"number":127,"text":"τῆς μὲν οὖν παρὰ Φοινίκων μαρτυρίας τί δεῖ προσθεῖναι πλέον; βλέπεται γὰρ τἀληθὲς ἰσχυρῶς ὡμολογημένον καὶ πολὺ δήπου προάγειν τῆς τοῦ νεὼ κατασκευῆς τὴν τῶν προγόνων ἡμῶν εἰς τὴν χώραν ἄφιξιν· ὅτε γὰρ αὐτὴν πᾶσαν πολέμῳ παρέλαβον, τότε τὸν νεὼν κατεσκεύασαν. καὶ ταῦτα σαφῶς ἐκ τῶν ἱερῶν γραμμάτων ὑπʼ ἐμοῦ δεδήλωται διὰ τῆς ἀρχαιολογίας."},{"number":128,"text":"Λέξω δὲ νῦν ἤδη τὰ παρὰ Χαλδαίοις ἀναγεγραμμένα καὶ ἱστορούμενα περὶ ἡμῶν, ἅπερ ἔχει πολλὴν ὁμολογίαν καὶ περὶ τῶν ἄλλων τοῖς ἡμετέροις γράμμασι."},{"number":129,"text":"μάρτυς δὲ τούτων Βηρῶσος ἀνὴρ Χαλδαῖος μὲν τὸ γένος, γνώριμος δὲ τοῖς περὶ παιδείαν ἀναστρεφομένοις, ἐπειδὴ περί τε ἀστρονομίας καὶ περὶ τῶν παρὰ Χαλδαίοις φιλοσοφουμένων αὐτὸς εἰς τοὺς Ἕλληνας ἐξήνεγκε τὰς συγγραφάς."},{"number":130,"text":"οὗτος τοίνυν ὁ Βηρῶσος ταῖς ἀρχαιοτάταις ἐπακολουθῶν ἀναγραφαῖς περί τε τοῦ γενομένου κατακλυσμοῦ καὶ τῆς ἐν αὐτῷ φθορᾶς τῶν ἀνθρώπων καθάπερ Μωσῆς οὕτως ἱστόρηκεν καὶ περὶ τῆς λάρνακος, ἐν ᾗ Νῶχος ὁ τοῦ γένους ἡμῶν ἀρχηγὸς διεσώθη προσενεχθείσης αὐτῆς ταῖς ἀκρωρείαις τῶν Ἀρμενίων ὀρῶν."},{"number":131,"text":"εἶτα τοὺς ἀπὸ Νώχου καταλέγων καὶ τοὺς χρόνους αὐτοῖς προστιθεὶς ἐπὶ Ναβοπαλάσσαρον παραγίνεται τὸν Βαβυλῶνος καὶ Χαλδαίων βασιλέα καὶ τὰς τούτου πράξεις ἀφηγούμενος λέγει,"},{"number":132,"text":"τίνα τρόπον πέμψας ἐπὶ τὴν Αἴγυπτον καὶ ἐπὶ τὴν ἡμετέραν γῆν τὸν υἱὸν τὸν ἑαυτοῦ Ναβοκοδρόσορον μετὰ πολλῆς δυνάμεως, ἐπειδήπερ ἀφεστῶτας αὐτοὺς ἐπύθετο, πάντων ἐκράτησεν καὶ τὸν ναὸν ἐνέπρησε τὸν ἐν Ἱεροσολύμοις ὅλως τε πάντα τὸν παρʼ ἡμῶν λαὸν ἀναστήσας εἰς Βαβυλῶνα μετῴκισεν, συνέβη δὲ καὶ τὴν πόλιν ἐρημωθῆναι χρόνον ἐτῶν ἑβδομήκοντα μέχρι Κύρου τοῦ Περσῶν βασιλέως."},{"number":133,"text":"κρατῆσαι δέ φησι τὸν Βαβυλώνιον Αἰγύπτου Συρίας Φοινίκης Ἀραβίας πάντας ὑπερβαλόμενον ταῖς πράξεσι τοὺς πρὸ αὐτοῦ Χαλδαίων καὶ Βαβυλωνίων βεβασιλευκότας."},{"number":134,"text":"[εἶθʼ ἑξῆς ὑποκαταβὰς ὀλίγον ὁ Βηρῶσος πάλιν παρατίθεται ἐν τῇ τῆς ἀρχαιότητος ἱστοριογραφίᾳ.] αὐτὰ δὲ παραθήσομαι τὰ τοῦ Βηρώσου τοῦτον ἔχοντα τὸν τρόπον·"},{"number":135,"text":"ἀκούσας δʼ ὁ πατὴρ αὐτοῦ Ναβοπαλάσαρος, ὅτι ὁ τεταγμένος σατράπης ἔν τε Αἰγύπτῳ καὶ τοῖς περὶ τὴν Συρίαν τὴν κοίλην καὶ τὴν Φοινίκην τόποις ἀποστάτης γέγονεν, οὐ δυνάμενος αὐτὸς ἔτι κακοπαθεῖν συστήσας τῷ υἱῷ Ναβοκοδροσόρῳ ὄντι ἔτι ἐν ἡλικίᾳ μέρη τινὰ τῆς δυνάμεως ἐξέπεμψεν ἐπʼ αὐτόν."},{"number":136,"text":"συμμίξας δὲ Ναβοκοδρόσορος τῷ ἀποστάτῃ καὶ παραταξάμενος αὐτοῦ τʼ ἐκράτει καὶ τὴν χώραν ἐξ ἀρχῆς ὑπὸ τὴν αὐτῶν βασιλείαν ἐποιήσατο. τῷ τε πατρὶ αὐτοῦ συνέβη Ναβοπαλασάρῳ κατὰ τοῦτον τὸν καιρὸν ἀρρωστήσαντι ἐν τῇ Βαβυλωνίων πόλει μεταλλάξαι τὸν βίον ἔτη βεβασιλευκότι κα."},{"number":137,"text":"αἰσθόμενος δὲ μετʼ οὐ πολὺ τὴν τοῦ πατρὸς τελευτὴν Ναβουκοδρόσορος, καταστήσας τὰ κατὰ τὴν Αἴγυπτον πράγματα καὶ τὴν λοιπὴν χώραν καὶ τοὺς αἰχμαλώτους Ἰουδαίων τε καὶ Φοινίκων καὶ Σύρων καὶ τῶν κατὰ τὴν Αἴγυπτον ἐθνῶν συντάξας τισὶ τῶν φίλων μετὰ τῆς βαρυτάτης δυνάμεως καὶ τῆς λοιπῆς ὠφελείας ἀνακομίζειν εἰς τὴν Βαβυλωνίαν, αὐτὸς ὁρμήσας ὀλιγοστὸς παρεγένετο διὰ τῆς ἐρήμου εἰς Βαβυλῶνα."},{"number":138,"text":"καταλαβὼν δὲ τὰ πράγματα διοικούμενα ὑπὸ Χαλδαίων καὶ διατηρουμένην τὴν βασιλείαν ὑπὸ τοῦ βελτίστου αὐτῶν, κυριεύσας ὁλοκλήρου τῆς πατρικῆς ἀρχῆς τοῖς μὲν αἰχμαλώτοις παραγενομένοις συνέταξεν [αὐτοῖς] κατοικίας ἐν τοῖς ἐπιτηδειοτάτοις τῆς Βαβυλωνίας τόποις ἀποδεῖξαι,"},{"number":139,"text":"αὐτὸς δὲ ἀπὸ τῶν ἐκ τοῦ πολέμου λαφύρων τό τε Βήλου ἱερὸν καὶ τὰ λοιπὰ κοσμήσας φιλοτίμως τήν τε ὑπάρχουσαν ἐξ ἀρχῆς πόλιν καὶ ἑτέραν ἔξωθεν προσχαρισάμενος καὶ ἀναγκάσας πρὸς τὸ μηκέτι δύνασθαι τοὺς πολιορκοῦντας τὸν ποταμὸν ἀναστρέφοντας ἐπὶ τὴν πόλιν κατασκευάζειν, περιεβάλετο τρεῖς μὲν τῆς ἔνδον πόλεως περιβόλους, τρεῖς δὲ τῆς ἔξω, τούτων δὲ τοὺς μὲν ἐξ ὀπτῆς πλίνθου καὶ ἀσφάλτου, τοὺς δὲ ἐξ αὐτῆς τῆς πλίνθου."},{"number":140,"text":"καὶ τειχίσας ἀξιολόγως τὴν πόλιν καὶ τοὺς πυλῶνας κοσμήσας ἱεροπρεπῶς προσκατεσκεύασεν τοῖς πατρικοῖς βασιλείοις ἕτερα βασίλεια ἐχόμενα ἐκείνων, [ὑπὲρ] ὧν ἀνάστημα καὶ τὴν λοιπὴν πολυτέλειαν μακρὸν ἴσως ἔσται ἐάν τις ἐξηγῆται, πλὴν ὄντα γε ὑπερβολὴν ὡς μεγάλα καὶ ὑπερήφανα συνετελέσθη ἡμέραις δεκαπέντε."},{"number":141,"text":"ἐν δὲ τοῖς βασιλείοις τούτοις ἀναλήμματα λίθινα ὑψηλὰ ἀνοικοδομήσας καὶ τὴν ὄψιν ἀποδοὺς ὁμοιοτάτην τοῖς ὄρεσι, καταφυτεύσας δένδρεσι παντοδαποῖς ἐξειργάσατο καὶ κατεσκεύασε τὸν καλούμενον κρεμαστὸν παράδεισον διὰ τὸ τὴν γυναῖκα αὐτοῦ ἐπιθυμεῖν τῆς ὀρείας διαθέσεως τεθραμμένην ἐν τοῖς κατὰ τὴν Μηδίαν τόποις."},{"number":142,"text":"Ταῦτα μὲν οὕτως ἱστόρηκεν περὶ τοῦ προειρημένου βασιλέως καὶ πολλὰ πρὸς τούτοις ἐν τῇ τρίτῃ βίβλῳ τῶν Χαλδαϊκῶν, ἐν ᾗ μέμφεται τοῖς Ἑλληνικοῖς συγγραφεῦσιν ὡς μάτην οἰομένοις ὑπὸ Σεμιράμεως τῆς Ἀσσυρίας κτισθῆναι τὴν Βαβυλῶνα καὶ τὰ θαυμάσια κατασκευασθῆναι περὶ αὐτὴν ὑπʼ ἐκείνης ἔργα ψευδῶς γεγραφόσι."},{"number":143,"text":"καὶ κατὰ ταῦτα τὴν μὲν τῶν Χαλδαίων ἀναγραφὴν ἀξιόπιστον ἡγητέον· οὐ μὴν ἀλλὰ κἀν τοῖς ἀρχείοις τῶν Φοινίκων σύμφωνα τοῖς ὑπὸ Βηρώσου λεγομένοις ἀναγέγραπται περὶ τοῦ τῶν Βαβυλωνίων βασιλέως, ὅτι καὶ τὴν Συρίαν καὶ τὴν Φοινίκην ἅπασαν ἐκεῖνος κατεστρέψατο."},{"number":144,"text":"περὶ τούτων γοῦν συμφωνεῖ καὶ Φιλόστρατος ἐν ταῖς ἱστορίαις μεμνημένος τῆς Τύρου πολιορκίας, καὶ Μεγασθένης ἐν τῇ τετάρτῃ τῶν Ἰνδικῶν, διʼ ἧς ἀποφαίνειν πειρᾶται τὸν προειρημένον βασιλέα τῶν Βαβυλωνίων Ἡρακλέους ἀνδρείᾳ καὶ μεγέθει πράξεων διενηνοχέναι· καταστρέψασθαι γὰρ αὐτόν φησι καὶ Λιβύης τὴν πολλὴν καὶ Ἰβηρίαν."},{"number":145,"text":"τὰ δὲ περὶ τοῦ ναοῦ προειρημένα τοῦ ἐν Ἱεροσολύμοις, ὅτι κατεπρήσθη μὲν ὑπὸ τῶν Βαβυλωνίων ἐπιστρατευσάντων, ἤρξατο δὲ πάλιν ἀνοικοδομεῖσθαι Κύρου τῆς Ἀσίας τὴν βασιλείαν παρειληφότος, ἐκ τῶν Βηρώσου σαφῶς ἐπιδειχθήσεται παρατεθέντων·"},{"number":146,"text":"λέγει γὰρ οὕτως διὰ τῆς τρίτης· Ναβοκοδρόσορος μὲν οὖν μετὰ τὸ ἄρξασθαι τοῦ προειρημένου τείχους ἐμπεσὼν εἰς ἀρρωστίαν μετήλλαξε τὸν βίον βεβασιλευκὼς ἔτη μγ, τῆς δὲ βασιλείας κύριος ἐγένετο ὁ υἱὸς αὐτοῦ Εὐειλμαράδουχος."},{"number":147,"text":"οὗτος προστὰς τῶν πραγμάτων ἀνόμως καὶ ἀσελγῶς ἐπιβουλευθεὶς ὑπὸ τοῦ τὴν ἀδελφὴν ἔχοντος αὐτοῦ Νηριγλισάρου ἀνῃρέθη βασιλεύσας ἔτη β. μετὰ δὲ τὸ ἀναιρεθῆναι τοῦτον διαδεξάμενος τὴν ἀρχὴν ὁ ἐπιβουλεύσας αὐτῷ Νηριγλίσαρος ἐβασίλευσεν ἔτη δ."},{"number":148,"text":"τούτου υἱὸς Λαβοροσοάρδοχος ἐκυρίευσε μὲν τῆς βασιλείας παῖς ὢν μῆνας θ, ἐπιβουλευθεὶς δὲ διὰ τὸ πολλὰ ἐμφαίνειν κακοήθη ὑπὸ τῶν φίλων ἀπετυμπανίσθη."},{"number":149,"text":"ἀπολομένου δὲ τούτου συνελθόντες οἱ ἐπιβουλεύσαντες αὐτῷ κοινῇ τὴν βασιλείαν περιέθηκαν Ναβοννήδῳ τινὶ τῶν ἐκ Βαβυλῶνος ὄντι ἐκ τῆς αὐτῆς ἐπισυστάσεως. ἐπὶ τούτου τὰ περὶ τὸν ποταμὸν τείχη τῆς Βαβυλωνίων πόλεως ἐξ ὀπτῆς πλίνθου καὶ ἀσφάλτου κατεκοσμήθη."},{"number":150,"text":"οὔσης δὲ τῆς βασιλείας αὐτοῦ ἐν τῷ ἑπτακαιδεκάτῳ ἔτει προεξεληλυθὼς Κῦρος ἐκ τῆς Περσίδος μετὰ δυνάμεως πολλῆς καταστρεψάμενος τὴν λοιπὴν βασιλείαν πᾶσαν ὥρμησεν ἐπὶ τῆς Βαβυλωνίας."},{"number":151,"text":"αἰσθόμενος δὲ Ναβόννηδος τὴν ἔφοδον αὐτοῦ, ἀπαντήσας μετὰ τῆς δυνάμεως καὶ παραταξάμενος, ἡττηθεὶς τῇ μάχῃ καὶ φυγὼν ὀλιγοστὸς συνεκλείσθη εἰς τὴν Βορσιππηνῶν πόλιν,"},{"number":152,"text":"Κῦρος δὲ Βαβυλῶνα καταλαβόμενος καὶ συντάξας τὰ ἔξω τῆς πόλεως τείχη κατασκάψαι διὰ τὸ λίαν αὐτῷ πραγματικὴν καὶ δυσάλωτον φανῆναι τὴν πόλιν ἀνέζευξεν ἐπὶ Βορσίππων ἐκπολιορκήσων τὸν Ναβόννηδον."},{"number":153,"text":"τοῦ δὲ Ναβοννήδου οὐχ ὑπομείναντος τὴν πολιορκίαν, ἀλλʼ ἐγχειρίσαντος αὑτὸν πρότερον, χρησάμενος Κῦρος φιλανθρώπως καὶ δοὺς οἰκητήριον αὐτῷ Καρμανίαν ἐξέπεμψεν ἐκ τῆς Βαβυλωνίας. Ναβόννηδος μὲν οὖν τὸ λοιπὸν τοῦ χρόνου διαγενόμενος ἐν ἐκείνῃ τῇ χώρᾳ κατέστρεψε τὸν βίον."},{"number":154,"text":"Ταῦτα σύμφωνον ἔχει ταῖς ἡμετέραις βίβλοις τὴν ἀλήθειαν· γέγραπται γὰρ ἐν αὐταῖς, ὅτι Ναβουχοδονόσορος ὀκτωκαιδεκάτῳ τῆς αὐτοῦ βασιλείας ἔτει τὸν παρʼ ἡμῖν ναὸν ἠρήμωσεν καὶ ἦν ἀφανὴς ἐπʼ ἔτη πεντήκοντα, δευτέρῳ δὲ τῆς Κύρου βασιλείας ἔτει τῶν θεμελίων ὑποβληθέντων δευτέρῳ πάλιν τῆς Δαρείου βασιλείας ἀπετελέσθη."},{"number":155,"text":"προσθήσω δὲ καὶ τὰς τῶν Φοινίκων ἀναγραφάς· οὐ γὰρ παραλειπτέον τῶν ἀποδείξεων τὴν περιουσίαν· ἔστι δὲ τοιαύτη τῶν χρόνων ἡ καταρίθμησις·"},{"number":156,"text":"ἐπʼ Ἰθωβάλου τοῦ βασιλέως ἐπολιόρκησε Ναβουχοδονόσορος τὴν Τύρον ἐπʼ ἔτη δεκατρία."},{"number":157,"text":"μετὰ τοῦτον ἐβασίλευσε Βαὰλ ἔτη δέκα. μετὰ τοῦτον δικασταὶ κατεστάθησαν, καὶ ἐδίκασαν Ἐκνίβαλος Βασλήχου μῆνας β, Χέλβης Ἀβδαίου μῆνας ι, Ἄββαρος ἀρχιερεὺς μῆνας γ, Μύττυνος καὶ Γεράστρατος τοῦ Ἀβδηλίμου δικασταὶ ἔτη [στιγμα], ὧν μεταξὺ ἐβασίλευσε Βαλάτορος ἐνιαυτὸν ἕνα."},{"number":158,"text":"τούτου τελευτήσαντος ἀποστείλαντες μετεπέμψαντο Μέρβαλον ἐκ τῆς Βαβυλῶνος, καὶ ἐβασίλευσεν ἔτη δ. τούτου τελευτήσαντος μετεπέμψαντο τὸν ἀδελφὸν αὐτοῦ Εἴρωμον, ὃς ἐβασίλευσεν ἔτη εἴκοσιν. ἐπὶ τούτου Κῦρος Περσῶν ἐδυνάστευσεν."},{"number":159,"text":"οὐκοῦν ὁ σύμπας χρόνος ἔτη νδ καὶ τρεῖς μῆνες πρὸς αὐτοῖς· ἑβδόμῳ μὲν γὰρ ἔτει τῆς Ναβουχοδονοσόρου βασιλείας ἤρξατο πολιορκεῖν Τύρον, τεσσαρεσκαιδεκάτῳ δʼ ἔτει τῆς Εἰρώμου Κῦρος ὁ Πέρσης τὸ κράτος παρέλαβεν."},{"number":160,"text":"καὶ σύμφωνα μὲν ἐπὶ τοῦ ναοῦ τοῖς ἡμετέροις γράμμασι τὰ Χαλδαίων καὶ Τυρίων, ὡμολογημένη δὲ καὶ ἀναντίρρητος ἡ περὶ τῶν εἰρημένων μοι μαρτυρία τῆς τοῦ γένους ἡμῶν ἀρχαιότητος. τοῖς μὲν οὖν μὴ σφόδρα φιλονείκοις ἀρκέσειν ὑπολαμβάνω τὰ προειρημένα."},{"number":161,"text":"Δεῖ δʼ ἄρα καὶ τῶν ἀπιστούντων μὲν τοῖς βαρβάροις ἀναγραφαῖς μόνοις δὲ τοῖς Ἕλλησι πιστεύειν ἀξιούντων ἀποπληρῶσαι τὴν ἐπιζήτησιν καὶ παρασχεῖν πολλοὺς καὶ τούτων ἐπισταμένους τὸ ἔθνος ἡμῶν καὶ καθʼ ὃ καιρὸς ἦν αὐτοῖς μνημονεύοντας παραθέσθαι ἐν ἰδίοις αὐτῶν συγγράμμασι."},{"number":162,"text":"Πυθαγόρας τοίνυν ὁ Σάμιος ἀρχαῖος ὤν, σοφίᾳ δὲ καὶ τῇ περὶ τὸ θεῖον εὐσεβείᾳ πάντων ὑπειλημμένος διενεγκεῖν τῶν φιλοσοφησάντων, οὐ μόνον ἐγνωκὼς τὰ παρʼ ἡμῖν δῆλός ἐστιν, ἀλλὰ καὶ ζηλωτὴς αὐτῶν ἐκ πλείστου γεγενημένος."},{"number":163,"text":"αὐτοῦ μὲν οὖν οὐδὲν ὁμολογεῖται σύγγραμμα, πολλοὶ δὲ τὰ περὶ αὐτὸν ἱστορήκασι, καὶ τούτων ἐπισημότατός ἐστιν Ἕρμιππος ἀνὴρ περὶ πᾶσαν ἱστορίαν ἐπιμελής."},{"number":164,"text":"λέγει τοίνυν ἐν τῷ πρώτῳ τῶν περὶ Πυθαγόρου βιβλίων, ὅτι Πυθαγόρας ἑνὸς αὐτοῦ τῶν συνουσιαστῶν τελευτήσαντος τοὔνομα Καλλιφῶντος τὸ γένος Κροτωνιάτου τὴν ἐκείνου ψυχὴν ἔλεγε συνδιατρίβειν αὐτῷ καὶ νύκτωρ καὶ μεθʼ ἡμέραν· καὶ ὅτι παρεκελεύετο μὴ διέρχεσθαι τόπον, ἐφʼ ὃν ὄνος ὀκλάσῃ, καὶ τῶν διψίων ὑδάτων ἀπέχεσθαι καὶ πάσης ἀπέχειν βλασφημίας."},{"number":165,"text":"εἶτα προστίθησι μετὰ ταῦτα καὶ τάδε· ταῦτα δὲ ἔπραττεν καὶ ἔλεγε τὰς Ἰουδαίων καὶ Θρᾳκῶν δόξας μιμούμενος καὶ μεταφέρων εἰς ἑαυτόν. λέγεται γὰρ ὡς ἀληθῶς ὁ ἀνὴρ ἐκεῖνος πολλὰ τῶν παρὰ Ἰουδαίοις νομίμων εἰς τὴν αὐτοῦ μετενεγκεῖν φιλοσοφίαν."},{"number":166,"text":"ἦν δὲ καὶ κατὰ πόλεις οὐκ ἄγνωστον ἡμῶν πάλαι τὸ ἔθνος, καὶ πολλὰ τῶν ἐθῶν εἴς τινας ἤδη διαπεφοιτήκει καὶ ζήλου παρʼ ἐνίοις ἠξιοῦτο. δηλοῖ δὲ ὁ Θεόφραστος ἐν τοῖς περὶ νόμων·"},{"number":167,"text":"λέγει γάρ, ὅτι κωλύουσιν οἱ Τυρίων νόμοι ξενικοὺς ὅρκους ὀμνύειν, ἐν οἷς μετά τινων ἄλλων καὶ τὸν καλούμενον ὅρκον κορβὰν καταριθμεῖ. παρʼ οὐδενὶ δʼ ἂν οὗτος εὑρεθείη πλὴν μόνοις Ἰουδαίοις, δηλοῖ δʼ ὡς ἂν εἴποι τις ἐκ τῆς Ἑβραίων μεθερμηνευόμενος διαλέκτου δῶρον θεοῦ."},{"number":168,"text":"καὶ μὴν οὐδὲ Ἡρόδοτος ὁ Ἁλικαρνασεὺς ἠγνόηκεν ἡμῶν τὸ ἔθνος, ἀλλὰ τρόπῳ τινὶ φαίνεται μεμνημένος· περὶ γὰρ Κόλχων ἱστορῶν ἐν τῇ δευτέρᾳ βίβλῳ φησὶν οὕτως·"},{"number":169,"text":"μοῦνοι δὲ πάντων, φησί, Κόλχοι καὶ Αἰγύπτιοι καὶ Αἰθίοπες περιτέμνονται ἀπʼ ἀρχῆς τὰ αἰδοῖα. Φοίνικες δὲ καὶ Σύριοι οἱ ἐν τῇ Παλαιστίνῃ καὶ οὗτοι ὁμολογοῦσι παρʼ Αἰγυπτίων μεμαθηκέναι."},{"number":170,"text":"Σύριοι δὲ οἱ περὶ Θερμώδοντα καὶ Παρθένιον ποταμὸν καὶ Μάκρωνες οἱ τούτοισιν ἀστυγείτονες ὄντες ἀπὸ Κόλχων φασὶ νεωστὶ μεμαθηκέναι· οὗτοι γάρ εἰσιν οἱ περιτεμνόμενοι ἀνθρώπων μοῦνοι καὶ οὗτοι Αἰγυπτίοισι φαίνονται ποιοῦντες κατὰ ταὐτά. αὐτῶν δὲ Αἰγυπτίων καὶ Αἰθιόπων οὐκ ἔχω εἰπεῖν ὁπότεροι παρὰ τῶν ἑτέρων ἐξέμαθον."},{"number":171,"text":"οὐκοῦν εἴρηκε Σύρους τοὺς ἐν τῇ Παλαιστίνῃ περιτέμνεσθαι· τῶν δὲ τὴν Παλαιστίνην κατοικούντων μόνοι τοῦτο ποιοῦσιν Ἰουδαῖοι· τοῦτο ἄρα γιγνώσκων εἴρηκεν περὶ αὐτῶν."},{"number":172,"text":"καὶ Χοιρίλος δὲ ἀρχαιότερος γενόμενος ποιητὴς μέμνηται τοῦ ἔθνους ἡμῶν, ὅτι συνεστράτευται Ξέρξῃ τῷ Περσῶν βασιλεῖ ἐπὶ τὴν Ἑλλάδα· καταριθμησάμενος γὰρ πάντα τὰ ἔθνη τελευταῖον καὶ τὸ ἡμέτερον ἐνέταξε λέγων·"},{"number":173,"text":"τῶν δʼ ὄπιθεν διέβαινε γένος θαυμαστὸν ἰδέσθαι, γλῶσσαν μὲν Φοίνισσαν ἀπὸ στομάτων ἀφιέντες, ᾤκεον δʼ ἐν Σολύμοις ὄρεσι πλατέῃ παρὰ λίμνῃ αὐχμαλέοι κορυφὰς τροχοκουράδες, αὐτὰρ ὕπερθεν ἵππων δαρτὰ πρόσωπʼ ἐφόρουν ἐσκληκότα καπνῷ."},{"number":174,"text":"δῆλον οὖν ἐστιν, ὡς οἶμαι, πᾶσιν ἡμῶν αὐτὸν μεμνῆσθαι τῷ καὶ τὰ Σόλυμα ὄρη ἐν τῇ ἡμετέρᾳ εἶναι χώρᾳ, ἃ κατοικοῦμεν, καὶ τὴν Ἀσφαλτῖτιν λεγομένην λίμνην· αὕτη γὰρ πασῶν τῶν ἐν τῇ Συρίᾳ [λίμνη] πλατυτέρα καὶ μείζων καθέστηκεν."},{"number":175,"text":"καὶ Χοιρίλος μὲν οὖν οὕτω μέμνηται ἡμῶν. ὅτι δὲ οὐ μόνον ἠπίσταντο τοὺς Ἰουδαίους, ἀλλὰ καὶ ἐθαύμαζον ὅσοις αὐτῶν ἐντύχοιεν οὐχ οἱ φαυλότατοι τῶν Ἑλλήνων, ἀλλʼ οἱ ἐπὶ σοφίᾳ μάλιστα τεθαυμασμένοι, ῥᾴδιον γνῶναι·"},{"number":176,"text":"Κλέαρχος γὰρ ὁ Ἀριστοτέλους ὢν μαθητὴς καὶ τῶν ἐκ τοῦ περιπάτου φιλοσόφων οὐδενὸς δεύτερος ἐν τῷ πρώτῳ περὶ ὕπνου βιβλίῳ φησὶν Ἀριστοτέλην τὸν διδάσκαλον αὐτοῦ περί τινος ἀνδρὸς Ἰουδαίου ταῦτα ἱστορεῖν, αὐτῷ τε τὸν λόγον Ἀριστοτέλει παρατιθείς· ἔστι δὲ οὕτω γεγραμμένον·"},{"number":177,"text":"ἀλλὰ τὰ μὲν πολλὰ μακρὸν ἂν εἴη λέγειν, ὅσα δʼ ἔχει τῶν ἐκείνου θαυμασιότητά τινα καὶ φιλοσοφίαν ὁμοίως διελθεῖν οὐ χεῖρον. σαφῶς δʼ ἴσθι, εἶπεν, Ὑπεροχίδη, θαυμαστὸν ὀνείροις ἴσα σοι δόξω λέγειν. καὶ ὁ Ὑπεροχίδης εὐλαβούμενος, διʼ αὐτὸ γάρ, ἔφη, τοῦτο καὶ ζητοῦμεν ἀκοῦσαι πάντες."},{"number":178,"text":"οὐκοῦν, εἶπεν ὁ Ἀριστοτέλης, κατὰ τὸ τῶν ῥητορικῶν παράγγελμα τὸ γένος αὐτοῦ πρῶτον διέλθωμεν, ἵνα μὴ ἀπειθῶμεν τοῖς τῶν ἀπαγγελιῶν διδασκάλοις. λέγε, εἶπεν ὁ Ὑπεροχίδης, εἴ τί σοι δοκεῖ."},{"number":179,"text":"κἀκεῖνος τοίνυν τὸ μὲν γένος ἦν Ἰουδαῖος ἐκ τῆς κοίλης Συρίας. οὗτοι δέ εἰσιν ἀπόγονοι τῶν ἐν Ἰνδοῖς φιλοσόφων, καλοῦνται δέ, ὥς φασιν, οἱ φιλόσοφοι παρὰ μὲν Ἰνδοῖς Καλανοί, παρὰ δὲ Σύροις Ἰουδαῖοι τοὔνομα λαβόντες ἀπὸ τοῦ τόπου· προσαγορεύεται γὰρ ὃν κατοικοῦσι τόπον Ἰουδαία. τὸ δὲ τῆς πόλεως αὐτῶν ὄνομα πάνυ σκολιόν ἐστιν· Ἱερουσαλήμην γὰρ αὐτὴν καλοῦσιν."},{"number":180,"text":"οὗτος οὖν ὁ ἄνθρωπος ἐπιξενούμενός τε πολλοῖς κἀκ τῶν ἄνω τόπων εἰς τοὺς ἐπιθαλαττίους ὑποκαταβαίνων Ἑλληνικὸς ἦν οὐ τῇ διαλέκτῳ μόνον, ἀλλὰ καὶ τῇ ψυχῇ."},{"number":181,"text":"καὶ τότε διατριβόντων ἡμῶν περὶ τὴν Ἀσίαν παραβαλὼν εἰς τοὺς αὐτοὺς τόπους ἄνθρωπος ἐντυγχάνει ἡμῖν τε καί τισιν ἑτέροις τῶν σχολαστικῶν πειρώμενος αὐτῶν τῆς σοφίας. ὡς δὲ πολλοῖς τῶν ἐν παιδείᾳ συνῳκείωτο, παρεδίδου τι μᾶλλον ὧν εἶχεν."},{"number":182,"text":"ταῦτʼ εἴρηκεν ὁ Ἀριστοτέλης παρὰ τῷ Κλεάρχῳ καὶ προσέτι πολλὴν καὶ θαυμάσιον καρτερίαν τοῦ Ἰουδαίου ἀνδρὸς ἐν τῇ διαίτῃ καὶ σωφροσύνην διεξιών. ἔνεστι δὲ τοῖς βουλομένοις ἐξ αὐτοῦ τὸ πλέον γνῶναι τοῦ βιβλίου· φυλάττομαι γὰρ ἐγὼ [τὰ] πλείω τῶν ἱκανῶν παρατίθεσθαι."},{"number":183,"text":"Κλέαρχος μὲν οὖν ἐν παρεκβάσει ταῦτʼ εἴρηκεν, τὸ γὰρ προκείμενον ἦν αὐτῷ καθʼ ἕτερον, οὕτως ἡμῶν μνημονεῦσαι. Ἑκαταῖος δὲ ὁ Ἀβδηρίτης, ἀνὴρ φιλόσοφος ἅμα καὶ περὶ τὰς πράξεις ἱκανώτατος, Ἀλεξάνδρῳ τῷ βασιλεῖ συνακμάσας καὶ Πτολεμαίῳ τῷ Λάγου συγγενόμενος, οὐ παρέργως ἀλλὰ περὶ αὐτῶν Ἰουδαίων συγγέγραφε βιβλίον, ἐξ οὗ βούλομαι κεφαλαιωδῶς ἐπιδραμεῖν ἔνια τῶν εἰρημένων."},{"number":184,"text":"καὶ πρῶτον ἐπιδείξω τὸν χρόνον· μνημονεύει γὰρ τῆς Πτολεμαίου περὶ Γάζαν πρὸς Δημήτριον μάχης· αὕτη δὲ γέγονεν ἑνδεκάτῳ μὲν ἔτει τῆς Ἀλεξάνδρου τελευτῆς, ἐπὶ δὲ ὀλυμπιάδος ἑβδόμης καὶ δεκάτης καὶ ἑκατοστῆς, ὡς ἱστορεῖ Κάστωρ."},{"number":185,"text":"προσθεὶς γὰρ ταύτην τὴν ὀλυμπιάδα φησίν· ἐπὶ ταύτης Πτολεμαῖος ὁ Λάγου ἐνίκα κατὰ Γάζαν μάχῃ Δημήτριον τὸν Ἀντιγόνου τὸν ἐπικληθέντα Πολιορκητήν. Ἀλέξανδρον δὲ τεθνάναι πάντες ὁμολογοῦσιν ἐπὶ τῆς ἑκατοστῆς τεσσαρεσκαιδεκάτης ὀλυμπιάδος. δῆλον οὖν, ὅτι καὶ κατʼ ἐκεῖνον καὶ κατὰ Ἀλέξανδρον ἤκμαζεν ἡμῶν τὸ ἔθνος."},{"number":186,"text":"λέγει τοίνυν ὁ Ἑκαταῖος πάλιν τάδε, ὅτι μετὰ τὴν ἐν Γάζῃ μάχην ὁ Πτολεμαῖος ἐγένετο τῶν περὶ Συρίαν τόπων ἐγκρατής, καὶ πολλοὶ τῶν ἀνθρώπων πυνθανόμενοι τὴν ἠπιότητα καὶ φιλανθρωπίαν τοῦ Πτολεμαίου συναπαίρειν εἰς Αἴγυπτον αὐτῷ καὶ κοινωνεῖν τῶν πραγμάτων ἠβουλήθησαν."},{"number":187,"text":"ὧν εἷς ἦν, φησίν, Ἐζεκίας ἀρχιερεὺς τῶν Ἰουδαίων, ἄνθρωπος τὴν μὲν ἡλικίαν ὡς ἑξηκονταὲξ ἐτῶν, τῷ δʼ ἀξιώματι τῷ παρὰ τοῖς ὁμοέθνοις μέγας καὶ τὴν ψυχὴν οὐκ ἀνόητος, ἔτι δὲ καὶ λέγειν δυνατὸς καὶ τοῖς περὶ τῶν πραγμάτων, εἴπερ τις ἄλλος, ἔμπειρος."},{"number":188,"text":"καίτοι, φησίν, οἱ πάντες ἱερεῖς τῶν Ἰουδαίων οἱ τὴν δεκάτην τῶν γινομένων λαμβάνοντες καὶ τὰ κοινὰ διοικοῦντες περὶ χιλίους μάλιστα καὶ πεντακοσίους εἰσίν."},{"number":189,"text":"πάλιν δὲ τοῦ προειρημένου μνημονεύων ἀνδρός οὗτος, φησίν, ὁ ἄνθρωπος τετευχὼς τῆς τιμῆς ταύτης καὶ συνήθης ἡμῖν γενόμενος, παραλαβών τινας τῶν μεθʼ ἑαυτοῦ τήν τε διαφορὰν ἀνέγνω πᾶσαν αὐτοῖς· εἶχεν γὰρ τὴν κατοίκησιν αὐτῶν καὶ τὴν πολιτείαν γεγραμμένην."},{"number":190,"text":"εἶτα Ἑκαταῖος δηλοῖ πάλιν, πῶς ἔχομεν πρὸς τοὺς νόμους, ὅτι πάντα πάσχειν ὑπὲρ τοῦ μὴ παραβῆναι τούτους προαιρούμεθα καὶ καλὸν εἶναι νομίζομεν."},{"number":191,"text":"τοιγαροῦν, φησί, καὶ κακῶς ἀκούοντες ὑπὸ τῶν ἀστυγειτόνων καὶ τῶν εἰσαφικνουμένων πάντες καὶ προπηλακιζόμενοι πολλάκις ὑπὸ τῶν Περσικῶν βασιλέων καὶ σατραπῶν οὐ δύνανται μεταπεισθῆναι τῇ διανοίᾳ, ἀλλὰ γεγυμνωμένως περὶ τούτων καὶ αἰκίαις καὶ θανάτοις δεινοτάτοις μάλιστα πάντων ἀπαντῶσι μὴ ἀρνούμενοι τὰ πάτρια."},{"number":192,"text":"παρέχεται δὲ καὶ τεκμήρια τῆς ἰσχυρογνωμοσύνης τῆς περὶ τῶν νόμων οὐκ ὀλίγα· φησὶ γάρ, Ἀλεξάνδρου ποτὲ ἐν Βαβυλῶνι γενομένου καὶ προελομένου τὸ τοῦ Βήλου πεπτωκὸς ἱερὸν ἀνακαθᾶραι καὶ πᾶσιν αὐτοῦ τοῖς στρατιώταις ὁμοίως φέρειν τὸν χοῦν προστάξαντος, μόνους τοὺς Ἰουδαίους οὐ προσσχεῖν, ἀλλὰ καὶ πολλὰς ὑπομεῖναι πληγὰς καὶ ζημίας ἀποτῖσαι μεγάλας, ἕως αὐτοῖς συγγνόντα τὸν βασιλέα δοῦναι τὴν ἄδειαν."},{"number":193,"text":"ἔτι γε μὴν τῶν εἰς τὴν χώραν, φησί, πρὸς αὐτοὺς ἀφικνουμένων νεὼς καὶ βωμοὺς κατασκευασάντων ἅπαντα ταῦτα κατέσκαπτον, καὶ τῶν μὲν ζημίαν τοῖς σατράπαις ἐξέτινον, περί τινων δὲ καὶ συγγνώμης μετελάμβανον. καὶ προσεπιτίθησιν, ὅτι δίκαιον ἐπὶ τούτοις αὐτούς ἐστι θαυμάζειν."},{"number":194,"text":"λέγει δὲ καὶ περὶ τοῦ πολυανθρωπότατον γεγονέναι ἡμῶν τὸ ἔθνος· πολλὰς μὲν γὰρ ἡμῶν, φησίν, ἀνασπάστους εἰς Βαβυλῶνα Πέρσαι πρότερον αὐτῶν ἐποίησαν μυριάδας, οὐκ ὀλίγαι δὲ καὶ μετὰ τὸν Ἀλεξάνδρου θάνατον εἰς Αἴγυπτον καὶ Φοινίκην μετέστησαν διὰ τὴν ἐν Συρίᾳ στάσιν."},{"number":195,"text":"ὁ δὲ αὐτὸς οὗτος ἀνὴρ καὶ τὸ μέγεθος τῆς χώρας ἣν κατοικοῦμεν καὶ τὸ κάλλος ἱστόρηκεν· τριακοσίας γὰρ μυριάδας ἀρουρῶν σχεδὸν τῆς ἀρίστης καὶ παμφορωτάτης χώρας νέμονται, φησίν· ἡ γὰρ Ἰουδαία τοσαύτη πλῆθός ἐστιν."},{"number":196,"text":"ἀλλὰ μὴν ὅτι καὶ τὴν πόλιν αὐτὴν τὰ Ἱεροσόλυμα καλλίστην τε καὶ μεγίστην ἐκ παλαιοτάτου κατοικοῦμεν καὶ περὶ πλήθους ἀνδρῶν καὶ περὶ τῆς τοῦ νεὼ κατασκευῆς οὕτως αὐτὸς διηγεῖται."},{"number":197,"text":"ἔστι γὰρ τῶν Ἰουδαίων τὰ μὲν πολλὰ ὀχυρώματα κατὰ τὴν χώραν καὶ κῶμαι, μία δὲ πόλις ὀχυρὰ πεντήκοντα μάλιστα σταδίων τὴν περίμετρον, ἣν οἰκοῦσι μὲν ἀνθρώπων περὶ δώδεκα μυριάδες, καλοῦσι δʼ αὐτὴν Ἱεροσόλυμα."},{"number":198,"text":"ἐνταῦθα δʼ ἐστὶ κατὰ μέσον μάλιστα τῆς πόλεως περίβολος λίθινος μῆκος ὡς πεντάπλεθρος, εὖρος δὲ πηχῶν ρ, ἔχων διπλᾶς πύλας, ἐν ᾧ βωμός ἐστι τετράγωνος ἀτμήτων συλλέκτων ἀργῶν λίθων οὕτως συγκείμενος, πλευρὰν μὲν ἑκάστην εἴκοσι πηχῶν, ὕψος δὲ δεκάπηχυ. καὶ παρʼ αὐτὸν οἴκημα μέγα, οὗ βωμός ἐστι καὶ λυχνίον ἀμφότερα χρυσᾶ δύο τάλαντα τὴν ὁλκήν."},{"number":199,"text":"ἐπὶ τούτων φῶς ἐστιν ἀναπόσβεστον καὶ τὰς νύκτας καὶ τὰς ἡμέρας. ἄγαλμα δὲ οὐκ ἔστιν οὐδὲ ἀνάθημα τὸ παράπαν οὐδὲ φύτευμα παντελῶς οὐδὲν οἷον ἀλσῶδες ἤ τι τοιοῦτον. διατρίβουσι δʼ ἐν αὐτῷ καὶ τὰς νύκτας καὶ τὰς ἡμέρας ἱερεῖς ἁγνείας τινὰς ἁγνεύοντες καὶ τὸ παράπαν οἶνον οὐ πίνοντες ἐν τῷ ἱερῷ."},{"number":200,"text":"ἔτι γε μὴν ὅτι καὶ Ἀλεξάνδρῳ τῷ βασιλεῖ συνεστρατεύσαντο καὶ μετὰ ταῦτα τοῖς διαδόχοις αὐτοῦ μεμαρτύρηκεν. οἷς δʼ αὐτὸς παρατυχεῖν φησιν ὑπʼ ἀνδρὸς Ἰουδαίου κατὰ τὴν στρατείαν γενομένοις, τοῦτο παραθήσομαι."},{"number":201,"text":"λέγει δʼ οὕτως· ἐμοῦ γοῦν ἐπὶ τὴν Ἐρυθρὰν θάλασσαν βαδίζοντος συνηκολούθει τις μετὰ τῶν ἄλλων τῶν παραπεμπόντων ἡμᾶς ἱππέων Ἰουδαίων ὄνομα Μοσόλλαμος, ἄνθρωπος ἱκανῶς κατὰ ψυχὴν εὔρωστος καὶ τοξότης δὴ πάντων ὁμολογουμένως καὶ τῶν Ἑλλήνων καὶ τῶν βαρβάρων ἄριστος."},{"number":202,"text":"οὗτος οὖν ὁ ἄνθρωπος διαβαδιζόντων πολλῶν κατὰ τὴν ὁδὸν καὶ μάντεώς τινος ὀρνιθευομένου καὶ πάντας ἐπισχεῖν ἀξιοῦντος ἠρώτησε, διὰ τί προσμένουσι."},{"number":203,"text":"δείξαντος δὲ τοῦ μάντεως αὐτῷ τὸν ὄρνιθα καὶ φήσαντος, ἐὰν μὲν αὐτοῦ μένῃ προσμένειν συμφέρειν πᾶσιν, ἂν δʼ ἀναστὰς εἰς τοὔμπροσθεν πέτηται προάγειν, ἐὰν δὲ εἰς τοὔπισθεν ἀναχωρεῖν αὖθις, σιωπήσας καὶ παρελκύσας τὸ τόξον ἔβαλε καὶ τὸν ὄρνιθα πατάξας ἀπέκτεινεν."},{"number":204,"text":"ἀγανακτούντων δὲ τοῦ μάντεως καί τινων ἄλλων καὶ καταρωμένων αὐτῷ, τί μαίνεσθε, ἔφη, κακοδαίμονες; εἶτα τὸν ὄρνιθα λαβὼν εἰς τὰς χεῖρας, πῶς γάρ, ἔφη, οὗτος τὴν αὐτοῦ σωτηρίαν οὐ προϊδὼν περὶ τῆς ἡμετέρας πορείας ἡμῖν ἄν τι ὑγιὲς ἀπήγγελλεν; εἰ γὰρ ἠδύνατο προγιγνώσκειν τὸ μέλλον, εἰς τὸν τόπον τοῦτον οὐκ ἂν ἦλθε φοβούμενος, μὴ τοξεύσας αὐτὸν ἀποκτείνῃ Μοσόλλαμος ὁ Ἰουδαῖος. ἀλλὰ τῶν μὲν Ἑκαταίου μαρτυριῶν ἅλις·"},{"number":205,"text":"τοῖς γὰρ βουλομένοις πλείω μαθεῖν τῷ βιβλίῳ ῥᾴδιόν ἐστιν ἐντυχεῖν. οὐκ ὀκνήσω δὲ καὶ τὸν ἐπʼ εὐηθείας διασυρμῷ, καθάπερ αὐτὸς οἴεται, μνήμην πεποιημένον ἡμῶν Ἀγαθαρχίδην ὀνομάσαι·"},{"number":206,"text":"διηγούμενος γὰρ τὰ περὶ Στρατονίκην, ὃν τρόπον ἦλθεν μὲν εἰς Συρίαν ἐκ Μακεδονίας καταλιποῦσα τὸν ἑαυτῆς ἄνδρα Δημήτριον, Σελεύκου δὲ γαμεῖν αὐτὴν οὐ θελήσαντος, ὅπερ ἐκείνη προσεδόκησεν, ποιουμένου [δὲ] τὴν ἀπὸ Βαβυλῶνος στρατείαν αὐτοῦ τὰ περὶ τὴν Ἀντιόχειαν ἐνεωτέρισεν."},{"number":207,"text":"εἶθʼ ὡς ἀνέστρεψεν ὁ βασιλεύς, ἁλισκομένης τῆς Ἀντιοχείας εἰς Σελεύκειαν φυγοῦσα, παρὸν αὐτῇ ταχέως ἀποπλεῖν ἐνυπνίῳ κωλύοντι πεισθεῖσα ἐλήφθη καὶ ἀπέθανεν."},{"number":208,"text":"ταῦτα προειπὼν ὁ Ἀγαθαρχίδης καὶ ἐπισκώπτων τῇ Στρατονίκῃ τὴν δεισιδαιμονίαν παραδείγματι χρῆται τῷ περὶ ἡμῶν λόγῳ καὶ γέγραφεν οὕτως·"},{"number":209,"text":"οἱ καλούμενοι Ἰουδαῖοι πόλιν οἰκοῦντες ὀχυρωτάτην πασῶν, ἣν καλεῖν Ἱεροσόλυμα συμβαίνει τοὺς ἐγχωρίους, ἀργεῖν εἰθισμένοι διʼ ἑβδόμης ἡμέρας καὶ μήτε τὰ ὅπλα βαστάζειν ἐν τοῖς εἰρημένοις χρόνοις μήτε γεωργίας ἅπτεσθαι μήτε ἄλλης ἐπιμελεῖσθαι λειτουργίας μηδεμιᾶς, ἀλλʼ ἐν τοῖς ἱεροῖς ἐκτετακότες τὰς χεῖρας εὔχεσθαι μέχρι τῆς ἑσπέρας,"},{"number":210,"text":"εἰσιόντος εἰς τὴν πόλιν Πτολεμαίου τοῦ Λάγου μετὰ τῆς δυνάμεως καὶ τῶν ἀνθρώπων ἀντὶ τοῦ φυλάττειν τὴν πόλιν διατηρούντων τὴν ἄνοιαν, ἡ μὲν πατρὶς εἰλήφει δεσπότην πικρόν, ὁ δὲ νόμος ἐξηλέγχθη φαῦλον ἔχων ἐθισμόν."},{"number":211,"text":"τὸ δὲ συμβὰν πλὴν ἐκείνων τοὺς ἄλλους πάντας δεδίδαχε τηνικαῦτα φυγεῖν εἰς ἐνύπνια καὶ τὴν περὶ τοῦ νόμου παραδεδομένην ὑπόνοιαν, ἡνίκα ἂν τοῖς ἀνθρωπίνοις λογισμοῖς περὶ τῶν διαπορουμένων ἐξασθενήσωσιν."},{"number":212,"text":"τοῦτο μὲν Ἀγαθαρχίδῃ καταγέλωτος ἄξιον δοκεῖ, τοῖς δὲ μὴ μετὰ δυσμενείας ἐξετάζουσι φαίνεται μέγα καὶ πολλῶν ἄξιον ἐγκωμίων, εἰ καὶ σωτηρίας καὶ πατρίδος ἄνθρωποί τινες νόμων φυλακὴν καὶ τὴν πρὸς θεὸν εὐσέβειαν ἀεὶ προτιμῶσιν."},{"number":213,"text":"Ὅτι δὲ οὐκ ἀγνοοῦντες ἔνιοι τῶν συγγραφέων τὸ ἔθνος ἡμῶν, ἀλλʼ ὑπὸ φθόνου τινὸς ἢ διʼ ἄλλας αἰτίας οὐχ ὑγιεῖς τὴν μνήμην παρέλιπον, τεκμήριον οἶμαι παρέξειν· Ἱερώνυμος γὰρ ὁ τὴν περὶ τῶν διαδόχων ἱστορίαν συγγεγραφὼς κατὰ τὸν αὐτὸν μὲν ἦν Ἑκαταίῳ χρόνον, φίλος δʼ ὢν Ἀντιγόνου τοῦ βασιλέως τὴν Συρίαν ἐπετρόπευεν·"},{"number":214,"text":"ἀλλʼ ὅμως Ἑκαταῖος μὲν καὶ βιβλίον ἔγραψεν περὶ ἡμῶν, Ἱερώνυμος δʼ οὐδαμοῦ κατὰ τὴν ἱστορίαν ἐμνημόνευσε καίτοι σχεδὸν ἐν τοῖς τόποις διατετριφώς· τοσοῦτον αἱ προαιρέσεις τῶν ἀνθρώπων διήνεγκαν. τῷ μὲν γὰρ ἐδόξαμεν καὶ σπουδαίας εἶναι μνήμης ἄξιοι, τῷ δὲ πρὸς τὴν ἀλήθειαν πάντως τι πάθος οὐκ εὔγνωμον ἐπεσκότησεν."},{"number":215,"text":"ἀρκοῦσι δὲ ὅμως εἰς τὴν ἀπόδειξιν τῆς ἀρχαιότητος αἵ τε Αἰγυπτίων καὶ Χαλδαίων καὶ Φοινίκων ἀναγραφαὶ πρὸς ἐκείναις τε τοσοῦτοι τῶν Ἑλλήνων συγγραφεῖς·"},{"number":216,"text":"ἔτι δὲ πρὸς τοῖς εἰρημένοις Θεόφιλος καὶ Θεόδοτος καὶ Μνασέας καὶ Ἀριστοφάνης καὶ Ἑρμογένης Εὐήμερός τε καὶ Κόνων καὶ Ζωπυρίων καὶ πολλοί τινες ἄλλοι τάχα, οὐ γὰρ ἔγωγε πᾶσιν ἐντετύχηκα τοῖς βιβλίοις, οὐ παρέργως ἡμῶν ἐμνημονεύκασιν."},{"number":217,"text":"οἱ πολλοὶ δὲ τῶν εἰρημένων ἀνδρῶν τῆς μὲν ἀληθείας τῶν ἐξ ἀρχῆς πραγμάτων διήμαρτον, ὅτι μὴ ταῖς ἱεραῖς ἡμῶν βίβλοις ἐνέτυχον, κοινῶς μέντοι περὶ τῆς ἀρχαιότητος ἅπαντες μεμαρτυρήκασιν, ὑπὲρ ἧς τὰ νῦν λέγειν προεθέμην."},{"number":218,"text":"ὁ μέντοι Φαληρεὺς Δημήτριος καὶ Φίλων ὁ πρεσβύτερος καὶ Εὐπόλεμος οὐ πολὺ τῆς ἀληθείας διήμαρτον. οἷς συγγιγνώσκειν ἄξιον· οὐ γὰρ ἐνῆν αὐτοῖς μετὰ πάσης ἀκριβείας τοῖς ἡμετέροις γράμμασι παρακολουθεῖν."},{"number":219,"text":"Ἓν ἔτι μοι κεφάλαιον ὑπολείπεται τῶν κατὰ τὴν ἀρχὴν προτεθέντων τοῦ λόγου, τὰς διαβολὰς καὶ τὰς λοιδορίας, αἷς κέχρηνταί τινες κατὰ τοῦ γένους ἡμῶν, ἀποδεῖξαι ψευδεῖς καὶ τοῖς γεγραφόσι ταύτας καθʼ ἑαυτῶν χρήσασθαι μάρτυσιν."},{"number":220,"text":"ὅτι μὲν οὖν καὶ ἑτέροις τοῦτο πολλοῖς συμβέβηκε διὰ τὴν ἐνίων δυσμένειαν, οἶμαι γιγνώσκειν τοὺς πλέον ταῖς ἱστορίαις ἐντυγχάνοντας· καὶ γὰρ ἐθνῶν τινες καὶ τῶν ἐνδοξοτάτων πόλεων ῥυπαίνειν τὴν εὐγένειαν καὶ τὰς πολιτείας ἐπεχείρησαν λοιδορεῖν,"},{"number":221,"text":"Θεόπομπος μὲν τὴν Ἀθηναίων, τὴν δὲ Λακεδαιμονίων Πολυκράτης, ὁ δὲ τὸν Τριπολιτικὸν γράψας, οὐ γὰρ δὴ Θεόπομπός ἐστιν ὡς οἴονταί τινες, καὶ τὴν Θηβαίων πόλιν προσέλαβεν, πολλὰ δὲ καὶ Τίμαιος ἐν ταῖς ἱστορίαις περὶ τῶν προειρημένων καὶ περὶ ἄλλων βεβλασφήμηκεν."},{"number":222,"text":"μάλιστα δὲ τοῦτο ποιοῦσι τοῖς ἐνδοξοτάτοις προσπλεκόμενοι, τινὲς μὲν διὰ φθόνον καὶ κακοήθειαν, ἄλλοι δὲ διὰ τοῦ καινολογεῖν μνήμης ἀξιωθήσεσθαι νομίζοντες. παρὰ μὲν οὖν τοῖς ἀνοήτοις ταύτης οὐ διαμαρτάνουσι τῆς ἐλπίδος, οἱ δʼ ὑγιαίνοντες τῇ κρίσει πολλὴν αὐτῶν μοχθηρίαν καταδικάζουσι."},{"number":223,"text":"Τῶν δὲ εἰς ἡμᾶς βλασφημιῶν ἤρξαντο μὲν Αἰγύπτιοι· βουλόμενοι δʼ ἐκείνοις τινὲς χαρίζεσθαι παρατρέπειν ἐπεχείρησαν τὴν ἀλήθειαν, οὔτε τὴν εἰς Αἴγυπτον ἄφιξιν ὡς ἐγένετο τῶν ἡμετέρων προγόνων ὁμολογοῦντες, οὔτε τὴν ἔξοδον ἀληθεύοντες."},{"number":224,"text":"αἰτίας δὲ πολλὰς ἔλαβον τοῦ μισεῖν καὶ φθονεῖν τὸ μὲν ἐξ ἀρχῆς, ὅτι κατὰ τὴν χώραν αὐτῶν ἐδυνάστευσαν ἡμῶν οἱ πρόγονοι κἀκεῖθεν ἀπαλλαγέντες ἐπὶ τὴν οἰκείαν πάλιν εὐδαιμόνησαν, εἶθʼ ἡ τούτων ὑπεναντιότης πολλὴν αὐτοῖς ἐνεποίησεν ἔχθραν, τοσοῦτον τῆς ἡμετέρας διαφερούσης εὐσεβείας πρὸς τὴν ὑπʼ ἐκείνων νενομισμένην, ὅσον θεοῦ φύσις ζῴων ἀλόγων διέστηκε."},{"number":225,"text":"κοινὸν μὲν γὰρ αὐτοῖς ἐστι πάτριον τὸ ταῦτα θεοὺς νομίζειν, ἰδίᾳ δὲ πρὸς ἀλλήλους ἐν ταῖς τιμαῖς αὐτῶν διαφέρονται. κοῦφοι δὲ καὶ ἀνόητοι παντάπασιν ἄνθρωποι κακῶς ἐξ ἀρχῆς εἰθισμένοι δοξάζειν περὶ θεῶν μιμήσασθαι μὲν τὴν σεμνότητα τῆς ἡμετέρας θεολογίας οὐκ ἐχώρησαν, ὁρῶντες δὲ ζηλουμένους ὑπὸ πολλῶν ἐφθόνησαν."},{"number":226,"text":"εἰς τοσοῦτον γὰρ ἦλθον ἀνοίας καὶ μικροψυχίας ἔνιοι τῶν παρʼ αὐτοῖς, ὥστʼ οὐδὲ ταῖς ἀρχαίαις αὐτῶν ἀναγραφαῖς ὤκνησαν ἐναντία λέγειν, ἀλλὰ καὶ σφίσιν αὐτοῖς ἐναντία γράφοντες ὑπὸ τυφλότητος τοῦ πάθους ἠγνόησαν."},{"number":227,"text":"Ἐφʼ ἑνὸς δὲ πρώτου στήσω τὸν λόγον, ᾧ καὶ μάρτυρι μικρὸν ἔμπροσθεν τῆς ἀρχαιότητος ἐχρησάμην."},{"number":228,"text":"ὁ γὰρ Μανεθὼς οὗτος ὁ τὴν Αἰγυπτιακὴν ἱστορίαν ἐκ τῶν ἱερῶν γραμμάτων μεθερμηνεύειν ὑπεσχημένος, προειπὼν τοὺς ἡμετέρους προγόνους πολλαῖς μυριάσιν ἐπὶ τὴν Αἴγυπτον ἐλθόντας κρατῆσαι τῶν ἐνοικούντων, εἶτʼ αὐτὸς ὁμολογῶν χρόνῳ πάλιν ὕστερον ἐκπεσόντας τὴν νῦν Ἰουδαίαν κατασχεῖν καὶ κτίσαντας Ἱεροσόλυμα τὸν νεὼ κατασκευάσασθαι, μέχρι μὲν τούτων ἠκολούθησε ταῖς ἀναγραφαῖς."},{"number":229,"text":"ἔπειτα δὲ δοὺς ἐξουσίαν αὑτῷ διὰ τοῦ φάναι γράψειν τὰ μυθευόμενα καὶ λεγόμενα περὶ τῶν Ἰουδαίων λόγους ἀπιθάνους παρενέβαλεν, ἀναμῖξαι βουλόμενος ἡμῖν πλῆθος Αἰγυπτίων λεπρῶν καὶ ἐπὶ ἄλλοις ἀρρωστήμασιν, ὥς φησι, φυγεῖν ἐκ τῆς Αἰγύπτου καταγνωσθέντων."},{"number":230,"text":"Ἀμένωφιν γὰρ βασιλέα προσθεὶς ψευδὲς ὄνομα καὶ διὰ τοῦτο χρόνον αὐτοῦ τῆς βασιλείας ὁρίσαι μὴ τολμήσας, καίτοι γε ἐπὶ τῶν ἄλλων βασιλέων ἀκριβῶς τὰ ἔτη προστιθείς, τούτῳ προσάπτει τινὰς μυθολογίας ἐπιλαθόμενος σχεδόν, ὅτι πεντακοσίοις ἔτεσι καὶ δεκαοκτὼ πρότερον ἱστόρηκε γενέσθαι τὴν τῶν ποιμένων ἔξοδον εἰς Ἱεροσόλυμα."},{"number":231,"text":"Τέθμωσις γὰρ ἦν βασιλεὺς ὅτε ἐξῄεσαν, ἀπὸ δὲ τούτων μεταξὺ τῶν βασιλέων κατʼ αὐτόν ἐστι τριακόσια ἐνενηκοντατρία ἔτη μέχρι τῶν δύο ἀδελφῶν Σέθω καὶ Ἑρμαίου, ὧν τὸν μὲν Σέθων Αἴγυπτον, τὸν δὲ Ἕρμαιον Δαναὸν μετονομασθῆναί φησιν, ὃν ἐκβαλὼν ὁ Σέθως ἐβασίλευσεν ἔτη νθ καὶ μετʼ αὐτὸν ὁ πρεσβύτερος τῶν υἱῶν αὐτοῦ Ῥάμψης ξ[στιγμα]."},{"number":232,"text":"τοσούτοις οὖν πρότερον ἔτεσιν ἀπελθεῖν ἐξ Αἰγύπτου τοὺς πατέρας ἡμῶν ὡμολογηκὼς εἶτα τὸν Ἀμένωφιν εἰσποιήσας ἐμβόλιμον βασιλέα φησὶν τοῦτον ἐπιθυμῆσαι θεῶν γενέσθαι θεατήν ὥσπερ Ὢρ εἷς τῶν πρὸ αὐτοῦ βεβασιλευκότων, ἀνενεγκεῖν δὲ τὴν ἐπιθυμίαν ὁμωνύμῳ μὲν αὐτῷ Ἀμενώφει πατρὸς δὲ Πάπιος ὄντι, θείας δὲ δοκοῦντι μετεσχηκέναι φύσεως κατά τε σοφίαν καὶ πρόγνωσιν τῶν ἐσομένων."},{"number":233,"text":"εἰπεῖν οὖν αὐτῷ τοῦτον τὸν ὁμώνυμον, ὅτι δυνήσεται θεοὺς ἰδεῖν, εἰ καθαρὰν ἀπό τε λεπρῶν καὶ τῶν ἄλλων μιαρῶν ἀνθρώπων τὴν χώραν ἅπασαν ποιήσειεν."},{"number":234,"text":"ἡσθέντα δὲ τὸν βασιλέα πάντας τοὺς τὰ σώματα λελωβημένους ἐκ τῆς Αἰγύπτου συναγαγεῖν γενέσθαι δὲ τοῦ πλήθους μυριάδας ὀκτώ·"},{"number":235,"text":"καὶ τούτους εἰς τὰς λιθοτομίας τὰς ἐν τῷ πρὸς ἀνατολὴν μέρει τοῦ Νείλου ἐμβαλεῖν αὐτόν, ὅπως ἐργάζοιντο καὶ τῶν ἄλλων Αἰγυπτίων οἱ ἐγκεχωρισμένοι. εἶναι δέ τινας ἐν αὐτοῖς καὶ τῶν λογίων ἱερέων φησὶ λέπρᾳ συγκεχυμένους."},{"number":236,"text":"τὸν δὲ Ἀμένωφιν ἐκεῖνον, τὸν σοφὸν καὶ μαντικὸν ἄνδρα, ὑποδεῖσαι πρὸς αὐτόν τε καὶ τὸν βασιλέα χόλον τῶν θεῶν, εἰ βιασθέντες ὀφθήσονται. καὶ προσθέμενον εἰπεῖν, ὅτι συμμαχήσουσί τινες τοῖς μιαροῖς καὶ τῆς Αἰγύπτου κρατήσουσιν ἐπʼ ἔτη δεκατρία, μὴ τολμῆσαι μὲν αὐτὸν εἰπεῖν ταῦτα τῷ βασιλεῖ, γραφὴν δὲ καταλιπόντα περὶ πάντων ἑαυτὸν ἀνελεῖν, ἐν ἀθυμίᾳ δὲ εἶναι τὸν βασιλέα."},{"number":237,"text":"κἄπειτα κατὰ λέξιν οὕτως γέγραφεν· τῶν δʼ ἐν ταῖς λατομίαις ὡς χρόνος ἱκανὸς διῆλθεν ταλαιπωρούντων, ἀξιωθεὶς ὁ βασιλεύς, ἵνα [πρὸς] κατάλυσιν αὐτοῖς καὶ σκέπην ἀπομερίσῃ, τὴν τότε τῶν ποιμένων ἐρημωθεῖσαν πόλιν Αὔαριν συνεχώρησεν· ἔστι δʼ ἡ πόλις κατὰ τὴν θεολογίαν ἄνωθεν Τυφώνιος."},{"number":238,"text":"οἱ δὲ εἰς ταύτην εἰσελθόντες καὶ τὸν τόπον τοῦτον [εἰς] ἀπόστασιν ἔχοντες ἡγεμόνα αὐτῶν λεγόμενόν τινα τῶν Ἡλιοπολιτῶν ἱερέων Ὀσάρσηφον ἐστήσαντο καὶ τούτῳ πειθαρχήσοντες ἐν πᾶσιν ὡρκωμότησαν."},{"number":239,"text":"ὁ δὲ πρῶτον μὲν αὐτοῖς νόμον ἔθετο μήτε προσκυνεῖν θεοὺς μήτε τῶν μάλιστα ἐν Αἰγύπτῳ θεμιστευομένων ἱερῶν ζῴων ἀπέχεσθαι μηδενός, πάντα δὲ θύειν καὶ ἀναλοῦν, συνάπτεσθαι δὲ μηδενὶ πλὴν τῶν συνομωμοσμένων."},{"number":240,"text":"τοιαῦτα δὲ νομοθετήσας καὶ πλεῖστα ἄλλα μάλιστα τοῖς Αἰγυπτίοις ἐθισμοῖς ἐναντιούμενα ἐκέλευσεν πολυχειρίᾳ τὰ τῆς πόλεως ἐπισκευάζειν τείχη καὶ πρὸς πόλεμον ἑτοίμους γίνεσθαι τὸν πρὸς Ἀμένωφιν τὸν βασιλέα."},{"number":241,"text":"αὐτὸς δὲ προσλαβόμενος μεθʼ ἑαυτοῦ καὶ τῶν ἄλλων ἱερέων καὶ συμμεμιαμμένων ἔπεμψε πρέσβεις πρὸς τοὺς ὑπὸ Τεθμώσεως ἀπελαθέντας ποιμένας εἰς πόλιν τὴν καλουμένην Ἱεροσόλυμα, καὶ τὰ καθʼ ἑαυτὸν καὶ τοὺς ἄλλους τοὺς συνατιμασθέντας δηλώσας ἠξίου συνεπιστρατεύειν ὁμοθυμαδὸν ἐπʼ Αἴγυπτον."},{"number":242,"text":"ἐπάξειν μὲν οὖν αὐτοὺς ἐπηγγείλατο πρῶτον μὲν εἰς Αὔαριν τὴν προγονικὴν αὐτῶν πατρίδα καὶ τὰ ἐπιτήδεια τοῖς ὄχλοις παρέξειν ἀφθόνως, ὑπερμαχήσεσθαι δὲ ὅτε δέοι καὶ ῥᾳδίως ὑποχείριον αὐτοῖς τὴν χώραν ποιήσειν."},{"number":243,"text":"οἱ δὲ ὑπερχαρεῖς γενόμενοι πάντες προθύμως εἰς κ μυριάδας ἀνδρῶν συνεξώρμησαν καὶ μετʼ οὐ πολὺ ἧκον εἰς Αὔαριν. Ἀμένωφις δʼ ὁ τῶν Αἰγυπτίων βασιλεὺς ὡς ἐπύθετο τὰ κατὰ τὴν ἐκείνων ἔφοδον, οὐ μετρίως συνεχύθη τῆς παρὰ Ἀμενώφεως τοῦ Παάπιος μνησθεὶς προδηλώσεως."},{"number":244,"text":"καὶ πρότερον συναγαγὼν πλῆθος Αἰγυπτίων καὶ βουλευσάμενος μετὰ τῶν ἐν τούτοις ἡγεμόνων τά τε ἱερὰ ζῷα τὰ [πρῶτα] μάλιστα ἐν τοῖς ἱεροῖς τιμώμενα ὥς γʼ ἑαυτὸν μετεπέμψατο καὶ τοῖς κατὰ μέρος ἱερεῦσι παρήγγελλεν ὡς ἀσφαλέστατα τῶν θεῶν συγκρύψαι τὰ ξόανα."},{"number":245,"text":"τὸν δὲ υἱὸν Σέθω τὸν καὶ Ῥαμεσσῆ ἀπὸ Ῥαψηοῦς τοῦ πατρὸς ὠνομασμένον πενταέτη ὄντα ἐξέθετο πρὸς τὸν ἑαυτοῦ φίλον. αὐτὸς δὲ διαβὰς τοῖς ἄλλοις Αἰγυπτίοις οὖσιν εἰς τριάκοντα μυριάδας ἀνδρῶν μαχιμωτάτων καὶ τοῖς πολεμίοις ἀπαντήσας οὐ συνέβαλεν,"},{"number":246,"text":"ἀλλὰ μέλλειν θεομαχεῖν νομίσας παλινδρομήσας ἧκεν εἰς Μέμφιν ἀναλαβών τε τόν τε Ἆπιν καὶ τὰ ἄλλα τὰ ἐκεῖσε μεταπεμφθέντα ἱερὰ ζῷα εὐθὺς εἰς Αἰθιοπίαν σὺν ἅπαντι τῷ στόλῳ καὶ πλήθει τῶν Αἰγυπτίων ἀνήχθη· χάριτι γὰρ ἦν αὐτῷ ὑποχείριος ὁ τῶν Αἰθιόπων βασιλεύς."},{"number":247,"text":"ὃς ὑποδεξάμενος καὶ τοὺς ὄχλους πάντας ὑπολαβὼν οἷς ἔσχεν ἡ χώρα τῶν πρὸς ἀνθρωπίνην τροφὴν ἐπιτηδείων, καὶ πόλεις καὶ κώμας πρὸς τὴν τῶν πεπρωμένων τρισκαίδεκα ἐτῶν ἀπὸ τῆς ἀρχῆς αὐτοῦ [εἰς τὴν] ἔκπτωσιν αὐτάρκεις, οὐχ ἧττον δὲ καὶ στρατόπεδον Αἰθιοπικὸν πρὸς φυλακὴν ἐπέταξε τοῖς παρʼ Ἀμενώφεως τοῦ βασιλέως ἐπὶ τῶν ὁρίων τῆς Αἰγύπτου."},{"number":248,"text":"καὶ τὰ μὲν κατὰ τὴν Αἰθιοπίαν τοιαῦτα. οἱ δὲ Σολυμῖται κατελθόντες σὺν τοῖς μιαροῖς τῶν Αἰγυπτίων οὕτως ἀνοσίως καὶ τοῖς ἀνθρώποις προσηνέχθησαν, ὥστε τὴν τῶν προειρημένων κράτησιν χρυσὸν φαίνεσθαι τοῖς τότε τὰ τούτων ἀσεβήματα θεωμένοις·"},{"number":249,"text":"καὶ γὰρ οὐ μόνον πόλεις καὶ κώμας ἐνέπρησαν οὐδὲ ἱεροσυλοῦντες οὐδὲ λυμαινόμενοι ξόανα θεῶν ἠρκοῦντο, ἀλλὰ καὶ τοῖς αὐτοῖς ὀπτανίοις τῶν σεβαστευομένων ἱερῶν ζῴων χρώμενοι διετέλουν καὶ θύτας καὶ σφαγεῖς τούτων ἱερεῖς καὶ προφήτας ἠνάγκαζον γίνεσθαι καὶ γυμνοὺς ἐξέβαλλον."},{"number":250,"text":"λέγεται δέ, ὅτι τὴν πολιτείαν καὶ τοὺς νόμους αὐτοῖς καταβαλόμενος ἱερεὺς τὸ γένος Ἡλιοπολίτης ὄνομα Ὀσαρσὶφ ἀπὸ τοῦ ἐν Ἡλιουπόλει θεοῦ Ὀσίρεως, ὡς μετέβη εἰς τοῦτο τὸ γένος, μετετέθη τοὔνομα καὶ προσηγορεύθη Μωυσῆς."},{"number":251,"text":"Ἃ μὲν οὖν Αἰγύπτιοι φέρουσι περὶ τῶν Ἰουδαίων ταῦτʼ ἐστὶ καὶ ἕτερα πλείονα, ἃ παρίημι συντομίας ἕνεκα. λέγει δὲ ὁ Μανεθὼς πάλιν, ὅτι μετὰ ταῦτα ἐπῆλθεν ὁ Ἀμένωφις ἀπὸ Αἰθιοπίας μετὰ μεγάλης δυνάμεως καὶ ὁ υἱὸς αὐτοῦ Ῥάμψης καὶ αὐτὸς ἔχων δύναμιν, καὶ συμβαλόντες οἱ δύο τοῖς ποιμέσι καὶ τοῖς μιαροῖς ἐνίκησαν αὐτοὺς καὶ πολλοὺς ἀποκτείναντες ἐδίωξαν αὐτοὺς ἄχρι τῶν ὁρίων τῆς Συρίας."},{"number":252,"text":"ταῦτα μὲν καὶ τὰ τοιαῦτα Μανεθὼς συνέγραψεν. ὅτι δὲ ληρεῖ καὶ ψεύδεται περιφανῶς, ἐπιδείξω προδιαστειλάμενος ἐκεῖνο τῶν ὕστερον πρὸς ἄλλους λεχθησομένων ἕνεκα· δέδωκε γὰρ οὗτος ἡμῖν καὶ ὡμολόγηκεν ἐξ ἀρχῆς τε μὴ εἶναι τὸ γένος Αἰγυπτίους, ἀλλʼ αὐτοὺς ἔξωθεν ἐπελθόντας κρατῆσαι τῆς Αἰγύπτου καὶ πάλιν ἐξ αὐτῆς ἀπελθεῖν."},{"number":253,"text":"ὅτι δʼ οὐκ ἀνεμίχθησαν ἡμῖν ὕστερον τῶν Αἰγυπτίων οἱ τὰ σώματα λελωβημένοι, καὶ ὅτι ἐκ τούτων οὐκ ἦν Μωυσῆς ὁ τὸν λαὸν ἀγαγών, ἀλλὰ πολλαῖς ἐγεγόνει γενεαῖς πρότερον, ταῦτα πειράσομαι διὰ τῶν ὑπʼ αὐτοῦ λεγομένων ἐλέγχειν."},{"number":254,"text":"Πρώτην δὴ τὴν αἰτίαν τοῦ πλάσματος ὑποτίθεται καταγέλαστον· ὁ βασιλεὺς γάρ φησιν Ἀμένωφις ἐπεθύμησε τοὺς θεοὺς ἰδεῖν. ποίους; εἰ μὲν τοὺς παρʼ αὐτοῖς νενομοθετημένους τὸν βοῦν καὶ τράγον καὶ κροκοδείλους καὶ κυνοκεφάλους, ἑώρα."},{"number":255,"text":"τοὺς οὐρανίους δὲ πῶς ἐδύνατο; καὶ διὰ τί ταύτην ἔσχε τὴν ἐπιθυμίαν; ὅτι νὴ Δία καὶ πρότερος αὐτοῦ βασιλεὺς ἄλλος ἑωράκει. παρʼ ἐκείνου τοίνυν ἐπέπυστο, ποταποί τινές εἰσι καὶ τίνα τρόπον αὐτοὺς εἶδεν, ὥστε καινῆς αὐτῷ τέχνης οὐκ ἔδει."},{"number":256,"text":"ἀλλὰ σοφὸς ἦν ὁ μάντις, διʼ οὗ τοῦτο κατορθώσειν ὁ βασιλεὺς ὑπελάμβανε. καὶ πῶς οὐ προέγνω τὸ ἀδύνατον αὐτοῦ τῆς ἐπιθυμίας; οὐ γὰρ ἀπέβη. τίνα δὲ καὶ λόγον εἶχε διὰ τοὺς ἠκρωτηριασμένους ἢ λεπρῶντας ἀφανεῖς εἶναι τοὺς θεούς; ὀργίζονται γὰρ ἐπὶ τοῖς ἀσεβήμασιν, οὐκ ἐπὶ τοῖς ἐλαττώμασι τῶν σωμάτων."},{"number":257,"text":"ὀκτὼ δὲ μυριάδας τῶν λεπρῶν καὶ κακῶς διακειμένων πῶς οἷόν τε μιᾷ σχεδὸν ἡμέρᾳ συλλεγῆναι; πῶς δὲ παρήκουσεν τοῦ μάντεως ὁ βασιλεύς; ὁ μὲν γὰρ αὐτὸν ἐκέλευσεν ἐξορίσαι τῆς Αἰγύπτου τοὺς λελωβημένους, ὁ δʼ αὐτοὺς εἰς τὰς λιθοτομίας ἐνέβαλεν, ὥσπερ τῶν ἐργασομένων δεόμενος, ἀλλʼ οὐχὶ καθᾶραι τὴν χώραν προαιρούμενος."},{"number":258,"text":"φησὶ δὲ τὸν μὲν μάντιν αὑτὸν ἀνελεῖν τὴν ὀργὴν τῶν θεῶν προορώμενον καὶ τὰ συμβησόμενα περὶ τὴν Αἴγυπτον, τῷ δὲ βασιλεῖ γεγραμμένην τὴν πρόρρησιν καταλιπεῖν. εἶτα πῶς οὐκ ἐξ ἀρχῆς ὁ μάντις τὸν αὑτοῦ θάνατον προηπίστατο;"},{"number":259,"text":"πῶς δὲ οὐκ εὐθὺς ἀντεῖπεν τῷ βασιλεῖ βουλομένῳ τοὺς θεοὺς ἰδεῖν; πῶς δʼ εὔλογος ὁ φόβος τῶν μὴ παρʼ αὐτὸν συμβησομένων κακῶν; ἦ τι χεῖρον ἔδει παθεῖν οὐδʼ ἂν ἑαυτὸν ἔσπευδεν. τὸ δὲ δὴ πάντων εὐηθέστατον ἴδωμεν·"},{"number":260,"text":"πυθόμενος γὰρ ταῦτα καὶ περὶ τῶν μελλόντων φοβηθεὶς τοὺς λελωβημένους ἐκείνους, ὧν αὐτῷ καθαρεῦσαι προείρητο τὴν Αἴγυπτον, οὐδὲ τότε τῆς χώρας ἐξήλασεν, ἀλλὰ δεηθεῖσιν αὐτοῖς ἔδωκε πόλιν, ὥς φησι, τὴν πάλαι μὲν οἰκηθεῖσαν ὑπὸ τῶν ποιμένων, Αὔαριν δὲ καλουμένην."},{"number":261,"text":"εἰς ἣν ἀθροισθέντας αὐτοὺς ἡγεμόνα φησὶν ἐξελέσθαι τῶν ἐξ Ἡλιουπόλεως πάλαι γεγονότων ἱερέων, καὶ τοῦτον αὐτοῖς εἰσηγήσασθαι μήτε θεοὺς προσκυνεῖν μήτε τῶν ἐπʼ Αἰγύπτῳ θρησκευομένων ζῴων ἀπέχεσθαι, πάντα δὲ θύειν καὶ κατεσθίειν, συνάπτεσθαι δὲ μηδενὶ πλὴν τῶν συνομωμοσμένων, ὅρκοις τε τὸ πλῆθος ἐνδησάμενον, ἦ μὴν τούτοις ἐμμενεῖν τοῖς νόμοις, καὶ τειχίσαντα τὴν Αὔαριν πρὸς τὸν βασιλέα πόλεμον ἐξενεγκεῖν."},{"number":262,"text":"καὶ προστίθησιν, ὅτι ἔπεμψεν εἰς Ἱεροσόλυμα παρακαλῶν ἐκείνους αὐτοῖς συμμαχεῖν καὶ δώσειν αὐτοῖς τὴν Αὔαριν ὑπισχνούμενος, εἶναι γὰρ αὐτὴν τοῖς ἐκ τῶν Ἱεροσολύμων ἀφιξομένοις προγονικήν, ἀφʼ ἧς ὁρμωμένους αὐτοὺς πᾶσαν τὴν Αἴγυπτον καθέξειν."},{"number":263,"text":"εἶτα τοὺς μὲν ἐπελθεῖν εἴκοσι στρατοῦ μυριάσι λέγει, τὸν βασιλέα δὲ τῶν Αἰγυπτίων Ἀμένωφιν οὐκ οἰόμενον δεῖν θεομαχεῖν εἰς τὴν Αἰθιοπίαν εὐθὺς ἀποδρᾶναι, τὸν δὲ Ἆπιν καί τινα τῶν ἄλλων ἱερῶν ζῴων παρατεθεικέναι τοῖς ἱερεῦσι διαφυλάττεσθαι κελεύσαντα."},{"number":264,"text":"εἶτα τοὺς Ἱεροσολυμίτας ἐπελθόντας τάς τε πόλεις ἀνιστάναι καὶ τὰ ἱερὰ κατακαίειν καὶ τοὺς ἱππέας ἀποσφάττειν, ὅλως τε μηδεμιᾶς ἀπέχεσθαι παρανομίας μηδὲ ὠμότητος."},{"number":265,"text":"ὁ δὲ τὴν πολιτείαν καὶ τοὺς νόμους αὐτοῖς καταβαλόμενος ἱερεύς, φησίν, ἦν τὸ γένος Ἡλιοπολίτης, ὄνομα δʼ Ὀσαρσὴφ ἀπὸ τοῦ ἐν Ἡλιουπόλει θεοῦ Ὀσίρεως, μεταθέμενος δὲ Μωυσῆν αὑτὸν προσηγόρευσε."},{"number":266,"text":"τρισκαιδεκάτῳ δέ φησιν ἔτει τὸν Ἀμένωφιν, τοσοῦτον γὰρ αὐτῷ χρόνον εἶναι τῆς ἐκπτώσεως πεπρωμένον, ἐξ Αἰθιοπίας ἐπελθόντα μετὰ πολλῆς στρατιᾶς καὶ συμβαλόντα τοῖς ποιμέσι καὶ τοῖς μιαροῖς νικῆσαί τε τῇ μάχῃ καὶ κτεῖναι πολλοὺς ἐπιδιώξαντα μέχρι τῶν τῆς Συρίας ὅρων."},{"number":267,"text":"Ἐν τούτοις πάλιν οὐ συνίησιν ἀπιθάνως ψευδόμενος· οἱ γὰρ λεπροὶ καὶ τὸ μετʼ αὐτῶν πλῆθος, εἰ καὶ πρότερον ὠργίζοντο τῷ βασιλεῖ καὶ τοῖς τὰ περὶ αὐτοὺς πεποιηκόσι κατὰ [τε] τὴν τοῦ μάντεως προαγόρευσιν, ἀλλʼ ὅτε τῶν λιθοτομιῶν ἐξῆλθον καὶ πόλιν παρʼ αὐτοῦ καὶ χώραν ἔλαβον, πάντως ἂν γεγόνεισαν πρᾳότεροι πρὸς αὐτόν."},{"number":268,"text":"εἰ δὲ δὴ κἀκεῖνον ἐμίσουν, ἰδίᾳ μὲν ἄνω ἐπεβούλευον, οὐκ ἂν δὲ πρὸς ἅπαντας ἤραντο πόλεμον, δῆλον ὅτι πλείστας ἔχοντες συγγενείας τοσοῦτοί γε τὸ πλῆθος ὄντες."},{"number":269,"text":"ὅμως δὲ καὶ τοῖς ἀνθρώποις πολεμεῖν διεγνωκότες οὐκ ἂν εἰς τοὺς αὐτῶν θεοὺς πολεμεῖν ἐτόλμησαν οὐδʼ ὑπεναντιωτάτους ἔθεντο νόμους τοῖς πατρίοις αὐτῶν καὶ οἷς ἐνετράφησαν."},{"number":270,"text":"δεῖ δὲ ἡμᾶς τῷ Μανεθῶνι χάριν ἔχειν, ὅτι ταύτης τῆς παρανομίας οὐχὶ τοὺς ἐξ Ἱεροσολύμων ἐλθόντας ἀρχηγοὺς γενέσθαι φησίν, ἀλλʼ αὐτοὺς ἐκείνους ὄντας Αἰγυπτίους καὶ τούτων μάλιστα τοὺς ἱερέας ἐπινοῆσαί τε ταῦτα καὶ ὁρκωμοτῆσαι τὸ πλῆθος."},{"number":271,"text":"ἐκεῖνο μέντοι πῶς οὐκ ἄλογον, τῶν μὲν οἰκείων αὐτοῖς καὶ τῶν φίλων συναποστῆναι οὐδένα μηδὲ τοῦ πολέμου τὸν κίνδυνον συνάρασθαι, πέμψαι δὲ τοὺς μιαροὺς εἰς Ἱεροσόλυμα καὶ τὴν παρʼ ἐκείνων ἐπάγεσθαι συμμαχίαν;"},{"number":272,"text":"ποίας αὐτοῖς φιλίας ἢ τίνος αὐτοῖς οἰκειότητος προϋπηργμένης; τοὐναντίον γὰρ ἦσαν πολέμιοι καὶ τοῖς ἔθεσι πλεῖστον διέφερον. ὁ δέ φησιν εὐθὺς ὑπακοῦσαι τοῖς ὑπισχνουμένοις, ὅτι τὴν Αἴγυπτον καθέξουσιν, ὥσπερ αὐτῶν οὐ σφόδρα τῆς χώρας ἐμπείρως ἐχόντων, ἧς βιασθέντες ἐκπεπτώκασιν."},{"number":273,"text":"εἰ μὲν οὖν ἀπόρως ἢ κακῶς ἔπραττον, ἴσως ἂν καὶ παρεβάλλοντο, πόλιν δὲ κατοικοῦντες εὐδαίμονα καὶ χώραν πολλὴν κρείττω τῆς Αἰγύπτου καρπούμενοι, διὰ τί ποτʼ ἂν ἐχθροῖς μὲν πάλαι τὰ δὲ σώματα λελωβημένοις, οὓς μηδὲ τῶν οἰκείων οὐδεὶς ὑπέμενε, τούτοις ἔμελλον παρακινδυνεύσειν βοηθοῦντες; οὐ γὰρ δή γε τὸν γενησόμενον προῄδεσαν δρασμὸν τοῦ βασιλέως·"},{"number":274,"text":"τοὐναντίον γὰρ αὐτὸς εἴρηκεν, ὡς ὁ παῖς τοῦ Ἀμενώφιος τριάκοντα μυριάδας ἔχων εἰς τὸ Πηλούσιον ὑπηντίαζεν. καὶ τοῦτο μὲν ᾔδεισαν πάντως οἱ παραγινόμενοι, τὴν δὲ μετάνοιαν αὐτοῦ καὶ τὴν φυγὴν πόθεν εἰκάζειν ἔμελλον;"},{"number":275,"text":"εἶτα κρατήσαντάς φησι τῆς Αἰγύπτου πολλὰ καὶ δεινὰ δρᾶν τοὺς ἐκ τῶν Ἱεροσολύμων ἐπιστρατεύσαντας καὶ περὶ τούτων ὀνειδίζει καθάπερ οὐ πολεμίους αὐτοῖς ἐπαγαγὼν ἢ δέον τοῖς ἔξωθεν ἐπικληθεῖσιν ἐγκαλεῖν, ὁπότε ταῦτα πρὸ τῆς ἐκείνων ἀφίξεως ἔπραττον καὶ πράξειν ὠμωμόκεσαν οἱ τὸ γένος Αἰγύπτιοι."},{"number":276,"text":"ἀλλὰ καὶ χρόνοις ὕστερον Ἀμένωφις ἐπελθὼν ἐνίκησε μάχῃ καὶ κτείνων τοὺς πολεμίους μέχρι τῆς Συρίας ἤλασεν. οὕτω γὰρ παντάπασίν ἐστιν ἡ Αἴγυπτος τοῖς ὁποθενδηποτοῦν ἐπιοῦσιν εὐάλωτος,"},{"number":277,"text":"καὶ οἱ τότε πολέμῳ κρατοῦντες αὐτὴν ζῆν πυνθανόμενοι τὸν Ἀμένωφιν οὔτε τὰς ἐκ τῆς Αἰθιοπίας ἐμβολὰς ὠχύρωσαν πολλὴν εἰς τοῦτο παρασκευὴν ἔχοντες οὔτε τὴν ἄλλην ἡτοίμασαν δύναμιν, ὁ δὲ καὶ μέχρι τῆς Συρίας ἀναιρῶν, φησίν, αὐτοὺς ἠκολούθησε διὰ τῆς ψάμμου τῆς ἀνύδρου, δῆλον ὅτι οὐ ῥᾴδιον οὐδὲ ἀμαχεὶ στρατοπέδῳ διελθεῖν."},{"number":278,"text":"Κατὰ μὲν οὖν τὸν Μανεθῶν οὔτε ἐκ τῆς Αἰγύπτου τὸ γένος ἡμῶν ἐστιν οὔτε τῶν ἐκεῖθέν τινες ἀνεμίχθησαν· τῶν γὰρ λεπρῶν καὶ νοσούντων πολλοὺς μὲν εἰκὸς ἐν ταῖς λιθοτομίαις ἀποθανεῖν πολὺν χρόνον ἐκεῖ γενομένους καὶ κακοπαθοῦντας, πολλοὺς δʼ ἐν ταῖς μετὰ ταῦτα μάχαις, πλείστους δʼ ἐν τῇ τελευταίᾳ καὶ τῇ φυγῇ."},{"number":279,"text":"Λοιπόν μοι πρὸς αὐτὸν εἰπεῖν περὶ Μωυσέως. τοῦτον δὲ τὸν ἄνδρα θαυμαστὸν μὲν Αἰγύπτιοι καὶ θεῖον νομίζουσι, βούλονται δὲ προσποιεῖν αὐτοῖς μετὰ βλασφημίας ἀπιθάνου, λέγοντες Ἡλιοπολίτην εἶναι τῶν ἐκεῖθεν ἱερέων ἕνα διὰ τὴν λέπραν συνεξεληλαμένον."},{"number":280,"text":"δείκνυται δʼ ἐν ταῖς ἀναγραφαῖς ὀκτωκαίδεκα σὺν τοῖς πεντακοσίοις πρότερον ἔτεσι γεγονὼς καὶ τοὺς ἡμετέρους ἐξαγαγὼν ἐκ τῆς Αἰγύπτου πατέρας εἰς τὴν χώραν τὴν νῦν οἰκουμένην ὑφʼ ἡμῶν."},{"number":281,"text":"ὅτι δὲ οὐδὲ συμφορᾷ τινι τοιαύτῃ περὶ τὸ σῶμα κεχρημένος ἦν, ἐκ τῶν λεγομένων ὑπʼ αὐτοῦ δῆλός ἐστι· τοῖς γὰρ λεπρῶσιν ἀπείρηκε μήτε μένειν ἐν πόλει μήτʼ ἐν κώμῃ κατοικεῖν, ἀλλὰ μόνους περιπατεῖν κατεσχισμένους τὰ ἱμάτια, καὶ τὸν ἁψάμενον αὐτῶν ἢ ὁμωρόφιον γενόμενον οὐ καθαρὸν ἡγεῖται."},{"number":282,"text":"καὶ μὴν κἂν θεραπευθῇ τὸ νόσημα καὶ τὴν αὑτοῦ φύσιν ἀπολάβῃ, προείρηκέν τινας ἁγνείας καθαρμοὺς πηγαίων ὑδάτων λουτροῖς καὶ ξυρήσεις πάσης τῆς τριχός, πολλάς τε κελεύει καὶ παντοίας ἐπιτελέσαντα θυσίας τότε παρελθεῖν εἰς τὴν ἱερὰν πόλιν."},{"number":283,"text":"καίτοι τοὐναντίον εἰκὸς ἦν προνοίᾳ τινὶ καὶ φιλανθρωπίᾳ χρήσασθαι τὸν ἐν τῇ συμφορᾷ ταύτῃ γεγονότα πρὸς τοὺς ὁμοίως αὐτῷ δυστυχήσαντας."},{"number":284,"text":"οὐ μόνον δὲ περὶ τῶν λεπρῶν οὕτως ἐνομοθέτησεν, ἀλλʼ οὐδὲ τοῖς καὶ τὸ βραχύτατόν τι τοῦ σώματος ἠκρωτηριασμένοις ἱερᾶσθαι συγκεχώρηκεν, ἀλλʼ εἰ καὶ μεταξύ τις ἱερώμενος τοιαύτῃ χρήσαιτο συμφορᾷ, τὴν τιμὴν αὐτὸν ἀφείλετο."},{"number":285,"text":"πῶς οὖν εἰκὸς ἐκεῖνον ταῦτα νομοθετεῖν ἀνοήτως ἀπὸ τοιούτων συμφορῶν συνειλεγμένους πρόεσθαι καθʼ ἑαυτῶν εἰς ὄνειδός τε καὶ βλάβην νόμους συντιθεμένους;"},{"number":286,"text":"ἀλλὰ μὴν καὶ τοὔνομα λίαν ἀπιθάνως μετατέθεικεν· Ὀσαρσὴφ γάρ, φησίν, ἐκαλεῖτο. τοῦτο μὲν οὖν εἰς τὴν μετάθεσιν οὐκ ἐναρμόζει, τὸ δʼ ἀληθὲς ὄνομα δηλοῖ τὸν ἐκ τοῦ ὕδατος σωθέντα [Μωσῆν]· τὸ γὰρ ὕδωρ οἱ Αἰγύπτιοι μῶϋ καλοῦσιν."},{"number":287,"text":"ἱκανῶς οὖν γεγονέναι νομίζω καὶ δῆλον δʼ ὅτι Μανεθὼς ἕως μὲν ἠκολούθει ταῖς ἀρχαίαις ἀναγραφαῖς οὐ πολὺ τῆς ἀληθείας διημάρτανεν, ἐπὶ δὲ τοὺς ἀδεσπότους μύθους τραπόμενος ἢ συνέθηκεν αὐτοὺς ἀπιθάνως ἤ τισι τῶν πρὸς ἀπέχθειαν εἰρηκότων ἐπίστευσεν."},{"number":288,"text":"Μετὰ τοῦτον ἐξετάσαι βούλομαι Χαιρήμονα· καὶ γὰρ οὗτος Αἰγυπτιακὴν φάσκων ἱστορίαν συγγράφειν καὶ προσθεὶς ταὐτὸ ὄνομα τοῦ βασιλέως ὅπερ ὁ Μανεθὼς Ἀμένωφιν καὶ τὸν υἱὸν αὐτοῦ Ῥαμεσσήν,"},{"number":289,"text":"φησὶν ὅτι κατὰ τοὺς ὕπνους ἡ Ἶσις ἐφάνη τῷ Ἀμενώφει μεμφομένη αὐτόν, ὅτι τὸ ἱερὸν αὐτῆς ἐν τῷ πολέμῳ κατέσκαπται. Φριτιβαύτην δὲ ἱερογραμματέα φάναι, ἐὰν τῶν τοὺς μολυσμοὺς ἐχόντων ἀνδρῶν καθάρῃ τὴν Αἴγυπτον, παύσεσθαι τῆς πτοίας αὐτόν."},{"number":290,"text":"ἐπιλέξαντα δὲ τῶν ἐπισινῶν μυριάδας εἰκοσιπέντε ἐκβαλεῖν. ἡγεῖσθαι δʼ αὐτῶν γραμματέας Μωσῆν τε καὶ Ἰώσηπον καὶ τοῦτον ἱερογραμματέα, Αἰγύπτια δʼ αὐτοῖς ὀνόματα εἶναι τῷ μὲν Μωσῇ Τισιθέν, τῷ δὲ Ἰωσήπῳ Πετεσήφ."},{"number":291,"text":"τούτους δʼ εἰς Πηλούσιον ἐλθεῖν καὶ ἐπιτυχεῖν μυριάσι τριακονταοκτὼ καταλελειμμέναις ὑπὸ τοῦ Ἀμενώφιος, ἃς οὐ θέλειν εἰς τὴν Αἴγυπτον διακομίζειν· οἷς φιλίαν συνθεμένους ἐπὶ τὴν Αἴγυπτον στρατεῦσαι."},{"number":292,"text":"τὸν δὲ Ἀμένωφιν οὐχ ὑπομείναντα τὴν ἔφοδον αὐτῶν εἰς Αἰθιοπίαν φυγεῖν καταλιπόντα τὴν γυναῖκα ἔγκυον, ἣν κρυβομένην ἔν τισι σπηλαίοις τεκεῖν παῖδα ὄνομα Ῥαμέσσην, ὃν ἀνδρωθέντα ἐκδιῶξαι τοὺς Ἰουδαίους εἰς τὴν Συρίαν ὄντας περὶ εἴκοσι μυριάδας καὶ τὸν πατέρα Ἀμένωφιν ἐκ τῆς Αἰθιοπίας καταδέξασθαι."},{"number":293,"text":"Καὶ ταῦτα μὲν ὁ Χαιρήμων. οἶμαι δὲ αὐτόθεν φανερὰν εἶναι ἐκ τῶν εἰρημένων τὴν ἀμφοῖν ψευδολογίαν· ἀληθείας μὲν γάρ τινος ὑποκειμένης ἀδύνατον ἦν διαφωνεῖν ἐπὶ τοσοῦτον, οἱ δὲ τὰ ψευδῆ συντιθέντες οὐχ ἑτέροις σύμφωνα γράφουσιν, ἀλλʼ αὐτοῖς τὰ δόξαντα πλάττουσιν."},{"number":294,"text":"ἐκεῖνος μὲν οὖν ἐπιθυμίαν τοῦ βασιλέως, ἵνα τοὺς θεοὺς ἴδῃ, φησὶν ἀρχὴν γενέσθαι τῆς τῶν μιαρῶν ἐκβολῆς, ὁ δὲ Χαιρήμων ἴδιον ὡς τῆς Ἴσιδος ἐνύπνιον συντέθεικε."},{"number":295,"text":"κἀκεῖνος μὲν Ἀμένωφιν εἶναι λέγει τὸν προειπόντα τῷ βασιλεῖ τὸν καθαρμόν, οὗτος δὲ Φριτοβαύτην· ὁ δὲ δὴ τοῦ πλήθους ἀριθμὸς καὶ σφόδρα σύνεγγυς, ὀκτὼ μὲν μυριάδας ἐκείνου λέγοντος, τούτου δὲ πέντε πρὸς ταῖς εἴκοσιν."},{"number":296,"text":"ἔτι τοίνυν ὁ μὲν Μανεθὼς πρότερον εἰς τὰς λιθοτομίας τοὺς μιαροὺς ἐκβαλὼν εἶτα αὐτοῖς τὴν Αὔαριν δοὺς ἐγκατοικεῖν καὶ τὰ πρὸς τοὺς ἄλλους Αἰγυπτίους ἐκπολεμώσας τότε φησὶν ἐπικαλέσασθαι τὴν παρὰ τῶν Ἱεροσολυμιτῶν αὐτοὺς ἐπικουρίαν,"},{"number":297,"text":"ὁ δὲ Χαιρήμων ἀπαλλαττομένους ἐκ τῆς Αἰγύπτου περὶ Πηλούσιον εὑρεῖν ὀκτὼ καὶ τριάκοντα μυριάδας ἀνθρώπων καταλελειμμένας ὑπὸ τοῦ Ἀμενώφιος καὶ μετʼ ἐκείνων πάλιν εἰς τὴν Αἴγυπτον ἐμβαλεῖν, φεύγειν δὲ τὸν Ἀμένωφιν εἰς τὴν Αἰθιοπίαν."},{"number":298,"text":"τὸ δὲ δὴ γενναιότατον, οὐδὲ τίνες ἢ πόθεν ἦσαν αἱ τοσαῦται τοῦ στρατοῦ μυριάδες εἴρηκεν εἴτε Αἰγύπτιοι τὸ γένος εἴτʼ ἔξωθεν ἥκοντες, ἀλλʼ οὐδὲ τὴν αἰτίαν διεσάφησε, διʼ ἣν αὐτοὺς ὁ βασιλεὺς εἰς τὴν Αἴγυπτον ἀνάγειν οὐκ ἠθέλησεν, ὁ περὶ τῶν λεπρῶν τὸ τῆς Ἴσιδος ἐνύπνιον συμπλάσας."},{"number":299,"text":"τῷ δὲ Μωσεῖ καὶ τὸν Ἰώσηπον ὁ Χαιρήμων ὡς ἐν ταὐτῷ χρόνῳ συνεξηλελαμένον προστέθεικεν τὸν πρὸ Μωυσέως πρεσβύτερον τέσσαρσι γενεαῖς τετελευτηκότα, ὧν ἐστιν ἔτη σχεδὸν ἑβδομήκοντα καὶ ἑκατόν."},{"number":300,"text":"ἀλλὰ μὴν ὁ Ῥαμέσσης ὁ τοῦ Ἀμενώφιος υἱὸς κατὰ μὲν τὸν Μανεθὼν νεανίας συμπολεμεῖ τῷ πατρὶ καὶ συνεκπίπτει φυγὼν εἰς τὴν Αἰθιοπίαν, οὗτος δὲ πεποίηκεν αὐτὸν μετὰ τὴν τοῦ πατρὸς τελευτὴν ἐν σπηλαίῳ τινὶ γεγενημένον καὶ μετὰ ταῦτα νικῶντα μάχῃ καὶ τοὺς Ἰουδαίους εἰς Συρίαν ἐξελαύνοντα τὸν ἀριθμὸν ὄντας περὶ μυριάδας κ."},{"number":301,"text":"ὢ τῆς εὐχερείας· οὔτε γὰρ πρότερον οἵτινες ἦσαν αἱ τριάκοντα καὶ ὀκτὼ μυριάδες εἶπεν οὔτε πῶς αἱ εἴκοσι καὶ τρεῖς διεφθάρησαν, πότερον ἐν τῇ μάχῃ κατέπεσον ἢ πρὸς τὸν Ῥαμεσσῆ μετεβάλοντο."},{"number":302,"text":"τὸ δὲ δὴ θαυμασιώτατον, οὐδὲ τίνας καλεῖ τοὺς Ἰουδαίους δυνατόν ἐστι παρʼ αὐτοῦ μαθεῖν ἢ ποτέροις αὐτοῖς τίθεται ταύτην τὴν προσηγορίαν, ταῖς κε μυριάσι τῶν λεπρῶν ἢ ταῖς η καὶ λ ταῖς περὶ τὸ Πηλούσιον."},{"number":303,"text":"ἀλλὰ γὰρ εὔηθες ἴσως ἂν εἴη διὰ πλειόνων ἐλέγχειν τοὺς ὑφʼ ἑαυτῶν ἐληλεγμένους· τὸ γὰρ ὑπʼ ἄλλων ἦν μετριώτερον."},{"number":304,"text":"Ἐπεισάξω δὲ τούτοις Λυσίμαχον εἰληφότα μὲν τὴν αὐτὴν τοῖς προειρημένοις ὑπόθεσιν τοῦ ψεύσματος περὶ τῶν λεπρῶν καὶ λελωβημένων, ὑπερπεπαικότα δὲ τὴν ἐκείνων ἀπιθανότητα τοῖς πλάσμασι, δῆλος συντεθεικὼς κατὰ πολλὴν ἀπέχθειαν·"},{"number":305,"text":"λέγει γὰρ ἐπὶ Βοχχόρεως τοῦ Αἰγυπτίων βασιλέως τὸν λαὸν τῶν Ἰουδαίων λεπροὺς ὄντας καὶ ψωροὺς καὶ ἄλλα νοσήματά τινα ἐχόντων εἰς τὰ ἱερὰ καταφεύγοντας μεταιτεῖν τροφήν. παμπόλλων δὲ ἀνθρώπων νοσηλείᾳ περιπεσόντων ἀκαρπίαν ἐν τῇ Αἰγύπτῳ γενέσθαι."},{"number":306,"text":"Βόχχοριν δὲ τὸν τῶν Αἰγυπτίων βασιλέα εἰς Ἄμμωνος πέμψαι περὶ τῆς ἀκαρπίας τοὺς μαντευσομένους, τὸν θεὸν δὲ ἐρεῖν τὰ ἱερὰ καθᾶραι ἀπʼ ἀνθρώπων ἀνάγνων καὶ δυσσεβῶν ἐκβάλλοντα αὐτοὺς ἐκ τῶν ἱερῶν εἰς τόπους ἐρήμους, τοὺς δὲ ψωροὺς καὶ λεπροὺς βυθίσαι, ὡς τοῦ ἡλίου ἀγανακτοῦντος ἐπὶ τῇ τούτων ζωῇ, καὶ τὰ ἱερὰ ἁγνίσαι καὶ οὕτω τὴν γῆν καρποφορήσειν."},{"number":307,"text":"τὸν δὲ Βόκχοριν τοὺς χρησμοὺς λαβόντα τούς τε ἱερεῖς καὶ ἐπιβωμίτας προσκαλεσάμενον κελεῦσαι ἐπιλογὴν ποιησαμένους τῶν ἀκαθάρτων τοῖς στρατιώταις τούτους παραδοῦναι κατάξειν αὐτοὺς εἰς τὴν ἔρημον, τοὺς δὲ λεπροὺς εἰς μολιβδίνους χάρτας ἐνδήσαντας, ἵνα καθῶσιν εἰς τὸ πέλαγος."},{"number":308,"text":"βυθισθέντων δὲ τῶν λεπρῶν καὶ ψωρῶν τοὺς ἄλλους συναθροισθέντας εἰς τόπους ἐρήμους ἐκτεθῆναι ἐπʼ ἀπωλείᾳ, συναχθέντας δὲ βουλεύσασθαι περὶ αὑτῶν, νυκτὸς δὲ ἐπιγενομένης πῦρ καὶ λύχνους καύσαντας φυλάττειν ἑαυτοὺς τήν τʼ ἐπιοῦσαν νύκτα νηστεύσαντας ἱλάσκεσθαι τοὺς θεοὺς περὶ τοῦ σῶσαι αὐτούς."},{"number":309,"text":"τῇ δʼ ἐπιούσῃ ἡμέρᾳ Μωσῆν τινα συμβουλεῦσαι αὐτοῖς παραβαλλομένοις μίαν ὁδὸν τέμνειν ἄχρι ἂν ὅτου ἔλθωσιν εἰς τόπους οἰκουμένους, παρακελεύσασθαί τε αὐτοῖς μήτε ἀνθρώπων τινὶ εὐνοήσειν μήτε ἄριστα συμβουλεύσειν ἀλλὰ τὰ χείρονα θεῶν τε ναοὺς καὶ βωμούς, οἷς ἂν περιτύχωσιν, ἀνατρέπειν."},{"number":310,"text":"συναινεσάντων δὲ τῶν ἄλλων τὰ δοχθέντα ποιοῦντας διὰ τῆς ἐρήμου πορεύεσθαι, ἱκανῶς δὲ ὀχληθέντας ἐλθεῖν εἰς τὴν οἰκουμένην χώραν καὶ τούς τε ἀνθρώπους ὑβρίζοντας καὶ τὰ ἱερὰ συλῶντας καὶ ἐμπρήσαντας ἐλθεῖν εἰς τὴν νῦν Ἰουδαίαν προσαγορευομένην, κτίσαντας δὲ πόλιν ἐνταῦθα κατοικεῖν."},{"number":311,"text":"τὸ δὲ ἄστυ τοῦτο Ἱερόσυλα ἀπὸ τῆς ἐκείνων διαθέσεως ὠνομάσθαι. ὕστερον δʼ αὐτοὺς ἐπικρατήσαντας χρόνῳ διαλλάξαι τὴν ὀνομασίαν πρὸς τὸ ὀνειδίζεσθαι καὶ τήν τε πόλιν Ἱεροσόλυμα καὶ αὐτοὺς Ἱεροσολυμίτας προσαγορεύεσθαι."},{"number":312,"text":"Οὗτος οὐδὲ τὸν αὐτὸν ἐκείνοις εὗρεν εἰπεῖν βασιλέα, καινότερον δʼ ὄνομα συντέθεικεν καὶ παρεὶς ἐνύπνιον καὶ προφήτην Αἰγύπτιον εἰς Ἄμμωνος ἀπελήλυθεν περὶ τῶν ψωρῶν καὶ λεπρῶν χρησμὸν οἴσων·"},{"number":313,"text":"φησὶ γὰρ εἰς τὰ ἱερὰ συλλέγεσθαι πλῆθος Ἰουδαίων. ἆρά γε τοῦτο τοῖς λεπροῖς ὄνομα θέμενος ἢ μόνον τῶν Ἰουδαίων τοῖς νοσήμασι περιπεσόντων; λέγει γάρ ὁ λαὸς τῶν Ἰουδαίων. ὁποῖος;"},{"number":314,"text":"ἔπηλυς ἢ τὸ γένος ἐγχώριος; διὰ τί τοίνυν Αἰγυπτίους αὐτοὺς ὄντας Ἰουδαίους καλεῖς; εἰ δὲ ξένοι, διὰ τί πόθεν οὐ λέγεις; πῶς δὲ τοῦ βασιλέως πολλοὺς μὲν αὐτῶν βυθίσαντος εἰς τὴν θάλασσαν, τοὺς δὲ λοιποὺς εἰς ἐρήμους τόπους ἐκβαλόντος, τοσοῦτοι τὸ πλῆθος ὑπελείφθησαν;"},{"number":315,"text":"ἢ τίνα τρόπον διεξῆλθον μὲν τὴν ἔρημον, ἐκράτησαν δὲ τῆς χώρας ἧς νῦν κατοικοῦμεν, ἔκτισαν δὲ καὶ πόλιν καὶ νεὼν ᾠκοδομήσαντο πᾶσι περιβόητον;"},{"number":316,"text":"ἐχρῆν δὲ καὶ τοῦ νομοθέτου μὴ μόνον εἰπεῖν τοὔνομα, δηλῶσαι δὲ καὶ τὸ γένος ὅστις ἦν καὶ τίνων, διὰ τί δὲ τοιούτους [ἂν] αὐτοῖς ἐπεχείρησε τιθέναι νόμους περὶ θεῶν καὶ τῆς πρὸς ἀνθρώπους ἀδικίας κατὰ τὴν πορείαν."},{"number":317,"text":"εἴτε γὰρ Αἰγύπτιοι τὸ γένος ἦσαν, οὐκ ἂν ἐκ τῶν πατρίων ἐθῶν οὕτω ῥᾳδίως μετεβάλοντο, εἴτʼ ἀλλαχόθεν ἦσαν, πάντως τινὲς ὑπῆρχον αὐτοῖς νόμοι διὰ μακρᾶς συνηθείας πεφυλαγμένοι."},{"number":318,"text":"εἰ μὲν οὖν περὶ τῶν ἐξελασάντων αὐτοὺς ὤμοσαν μηδέποτε εὐνοήσειν, λόγον εἶχεν εἰκότα, πᾶσι δὲ πόλεμον ἀνθρώποις ἀκήρυκτον ἄρασθαι τούτους, εἴπερ ἔπραττον ὡς αὐτὸς λέγει κακῶς, παρὰ πάντων βοηθείας δεομένους ἄνοιαν οὐκ ἐκείνων, ἀλλὰ τοῦ ψευδομένου πάνυ πολλὴν παρίστησιν, ὅς γε καὶ τοὔνομα θέσθαι τῇ πόλει ἀπὸ τῆς ἱεροσυλίας αὐτοὺς ἐτόλμησεν εἰπεῖν, τοῦτο δὲ μετὰ ταῦτα παρατρέψαι·"},{"number":319,"text":"δῆλον γάρ, ὅτι τοῖς μὲν ὕστερον γενομένοις αἰσχύνην τοὔνομα καὶ μῖσος ἔφερεν, αὐτοὶ δʼ οἱ κτίζοντες τὴν πόλιν κοσμήσειν αὐτοὺς ὑπελάμβανον οὕτως ὀνομάσαντες. ὁ δὲ γενναῖος ὑπὸ πολλῆς τοῦ λοιδορεῖν ἀκρασίας οὐ συνῆκεν, ὅτι ἱεροσυλεῖν οὐ κατὰ τὴν αὐτὴν φωνὴν Ἰουδαῖοι τοῖς Ἕλλησιν ὀνομάζομεν."},{"number":320,"text":"τί οὖν ἐπὶ πλείω τις λέγοι πρὸς τὸν ψευδόμενον οὕτως ἀναισχύντως; ἀλλʼ ἐπειδὴ σύμμετρον ἤδη τὸ βιβλίον εἴληφε μέγεθος, ἑτέραν ποιησάμενος ἀρχὴν τὰ λοιπὰ τῶν εἰς τὸ προκείμενον πειράσομαι προσαποδοῦναι."}]},"count":320,"chapterMarkers":false};})();